insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('como-se-encuentra-rapido-lo-que-esta-guardado-en-una-organizacio','tecnologia',array['negocios']::text[],'¿Cómo se encuentra rápido lo que está guardado en una organización?','Estudia cómo se organiza la información en una organización y diseña una forma de encontrarla en menos tiempo.','Análisis','~25 h',25,array['Gestión de la información','Búsqueda','Organización']::text[],array['investigar','resolver','otro-sector']::text[],'ficticios','sin','ingenieria de sistemas gestion de la informacion bibliotecologia administracion contabilidad secretariado ingenieria industrial computacion e informatica gestion de la informacion. organizacion de documentos. analisis de procesos. medicion de tiempos. redaccion de manuales. hoja de calculo. herramientas de almacenamiento y busqueda compartida. herramienta de diagramas.',$f57dbef${"id": "como-se-encuentra-rapido-lo-que-esta-guardado-en-una-organizacio", "area": "tecnologia", "areas2": ["negocios"], "titulo": "¿Cómo se encuentra rápido lo que está guardado en una organización?", "resumen": "Estudia cómo se organiza la información en una organización y diseña una forma de encontrarla en menos tiempo.", "tipo": "Análisis", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Gestión de la información", "Búsqueda", "Organización"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios o propios: trabaja con una organización inventada o con las carpetas de un grupo que te dé permiso.", "prog": "sin", "progTexto": "Sin programación: se puede hacer completo con documentos y hoja de cálculo.", "carreras": ["Ingeniería de Sistemas", "Gestión de la Información", "Bibliotecología", "Administración", "Contabilidad", "Secretariado", "Ingeniería Industrial", "Computación e Informática"], "problema": ["En una organización, la información vive en correos, carpetas, chats, hojas y la cabeza de algunas personas. Encontrar un documento puede tomar minutos que, multiplicados por muchas personas y muchos días, son un costo enorme.", "Cuando alguien se va, se pierde lo que solo él sabía dónde estaba. Y no existen reglas comunes sobre cómo nombrar, clasificar y guardar."], "desarrollar": ["Elige una organización pequeña real o inventada y haz una lista de los tipos de información que maneja y dónde está cada uno. Mide con tres personas cuánto tardan en encontrar cinco documentos típicos y qué obstáculos aparecen.", "Diseña un esquema de organización con nombres de carpetas, etiquetas y reglas simples, y vuelve a medir. El resultado puede ser un manual de una página y una comparación de tiempos antes y después."], "ampliaciones": [{"titulo": "Un mapa de la información", "aporta": "dibuja qué información entra, quién la guarda y dónde queda."}, {"titulo": "La cultura del orden", "aporta": "diseña una capacitación breve para que el equipo aplique las reglas."}, {"titulo": "Un buscador propio", "aporta": "prueba una herramienta de búsqueda y compara cuánto ayuda frente a solo ordenar."}], "objetivos": ["Inventariar la información de una organización.", "Medir cuánto tardan en encontrarla.", "Diseñar un esquema de organización con reglas claras.", "Comparar los tiempos antes y después.", "Redactar un manual sencillo para el equipo."], "habilidades": ["Gestión de la información.", "Organización de documentos.", "Análisis de procesos.", "Medición de tiempos.", "Redacción de manuales."], "herramientas": ["Hoja de cálculo.", "Herramientas de almacenamiento y búsqueda compartida.", "Herramienta de diagramas."], "lineamientos": ["Si observas a personas reales, avísales y pide permiso, y no copies documentos confidenciales en tu informe.", "Propón reglas que el equipo pueda seguir sin esfuerzo: un esquema complejo se abandona rápido."], "otroSector": "Funciona igual en un consultorio, una notaría, una parroquia, un taller, un colegio o la oficina de un negocio familiar."}$f57dbef$::jsonb,25),
('que-pasa-cuando-dos-personas-editan-lo-mismo-a-la-vez','tecnologia','{}'::text[],'¿Qué pasa cuando dos personas editan lo mismo a la vez?','Provoca conflictos entre dos usuarios o dos dispositivos que modifican el mismo dato y compara distintas formas de resolverlos.','Investigación','~25 h',25,array['Sincronización','Bases de datos','Concurrencia']::text[],array['investigar']::text[],'ficticios','opcional','ingenieria de sistemas ingenieria de software computacion e informatica ciencia de datos administracion analisis de sistemas concurrencia y sincronizacion. bases de datos. diseno de reglas. analisis de casos. comunicacion tecnica. una hoja compartida o una aplicacion de notas. hoja de calculo. opcionalmente un gestor de bases de datos.',$f7f86a1${"id": "que-pasa-cuando-dos-personas-editan-lo-mismo-a-la-vez", "area": "tecnologia", "areas2": [], "titulo": "¿Qué pasa cuando dos personas editan lo mismo a la vez?", "resumen": "Provoca conflictos entre dos usuarios o dos dispositivos que modifican el mismo dato y compara distintas formas de resolverlos.", "tipo": "Investigación", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Sincronización", "Bases de datos", "Concurrencia"], "intencion": ["investigar"], "datos": "ficticios", "datosTexto": "ficticios: crea un archivo o una tabla de prueba con datos inventados.", "prog": "opcional", "progTexto": "Programación opcional: puedes empezar sin programar y sumarla si quieres ir más lejos.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Computación e Informática", "Ciencia de Datos", "Administración", "Análisis de Sistemas"], "problema": ["Cuando dos personas, o la misma persona desde su celular y su computadora, modifican el mismo dato a la vez, uno de los cambios se pierde o los dos se mezclan mal. Pasa en hojas compartidas, en aplicaciones de notas y en sistemas de reservas.", "Evitarlo no es solo cuestión de técnica: hay que decidir qué cambio gana, si se avisa y cómo se conserva el otro."], "desarrollar": ["Prepara una tabla de prueba y simula tres situaciones: dos personas editan celdas distintas, la misma celda a la vez, y una persona edita sin conexión mientras otra sigue en línea. Registra qué pasa con cada cambio en cada caso.", "Compara tres estrategias: la última escritura gana, bloquear mientras alguien edita y fusionar los cambios. El resultado puede ser una tabla comparativa con ventajas y riesgos de cada estrategia."], "ampliaciones": [{"titulo": "Con una herramienta real", "aporta": "prueba cómo reacciona una hoja compartida o una aplicación de notas y describe su estrategia."}, {"titulo": "Un caso crítico", "aporta": "analiza qué pasaría si el dato fuera un saldo o un cupo limitado."}, {"titulo": "Un prototipo", "aporta": "programa una pequeña simulación que aplique las tres estrategias."}], "objetivos": ["Reproducir conflictos de edición simultánea.", "Observar sus efectos sobre los datos.", "Comparar estrategias de resolución.", "Evaluar riesgos según el tipo de dato.", "Presentar recomendaciones claras."], "habilidades": ["Concurrencia y sincronización.", "Bases de datos.", "Diseño de reglas.", "Análisis de casos.", "Comunicación técnica."], "herramientas": ["Una hoja compartida o una aplicación de notas.", "Hoja de cálculo.", "Opcionalmente un gestor de bases de datos."], "lineamientos": ["Trabaja con datos de prueba, nunca con información real de otras personas.", "Explica con ejemplos cotidianos para que alguien sin formación técnica entienda el problema."], "otroSector": "El mismo problema aparece al vender el último boleto de un evento, reservar una cita o repartir un stock limitado entre varias tiendas."}$f7f86a1$::jsonb,26),
('un-tablero-con-los-datos-publicos-de-tu-distrito','tecnologia',array['sociedad','ciudades']::text[],'Un tablero con los datos públicos de tu distrito','Reúne datos públicos dispersos de tu distrito y preséntalos en un tablero claro que cualquier vecino pueda entender y usar.','Prototipo','~30 h',30,array['Datos abiertos','Visualización','Comunidad']::text[],array['crear','resolver','otro-sector']::text[],'publicos','opcional','ingenieria de sistemas estadistica sociologia trabajo social administracion publica economia comunicaciones computacion e informatica datos abiertos y su licencia. visualizacion de datos. limpieza y combinacion de tablas. comunicacion para el ciudadano. pensamiento critico sobre las fuentes. hoja de calculo. herramientas gratuitas de tableros y graficos. portales de datos abiertos.',$f69feca${"id": "un-tablero-con-los-datos-publicos-de-tu-distrito", "area": "tecnologia", "areas2": ["sociedad", "ciudades"], "titulo": "Un tablero con los datos públicos de tu distrito", "resumen": "Reúne datos públicos dispersos de tu distrito y preséntalos en un tablero claro que cualquier vecino pueda entender y usar.", "tipo": "Prototipo", "tiempo": "~30 h", "horas": 30, "etiquetas": ["Datos abiertos", "Visualización", "Comunidad"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "publicos", "datosTexto": "públicos: usa datos abiertos de instituciones públicas sobre tu distrito, como población, servicios, seguridad vial o educación.", "prog": "opcional", "progTexto": "Programación opcional: puedes empezar sin programar y sumarla si quieres ir más lejos.", "carreras": ["Ingeniería de Sistemas", "Estadística", "Sociología", "Trabajo Social", "Administración Pública", "Economía", "Comunicaciones", "Computación e Informática"], "problema": ["Muchas instituciones publican datos abiertos, pero están repartidos en portales distintos, en formatos difíciles y sin una explicación que ayude a interpretarlos. El ciudadano común no los usa porque no sabe por dónde empezar.", "Por eso, decisiones locales sobre salud, tránsito o servicios suelen tomarse sin mirar lo que los propios datos públicos ya dicen."], "desarrollar": ["Elige tres o cuatro temas de interés para tu distrito y busca los datos públicos que los respaldan. Limpia y combina esas fuentes en una sola tabla y diseña un tablero con tres a cinco gráficos que respondan preguntas concretas, como «¿qué zona tiene menos servicios?».", "Cada gráfico debe tener un título que diga lo que se ve y una frase que explique cómo leerlo. El resultado puede ser una hoja con gráficos, un tablero de una herramienta gratuita o una página sencilla."], "ampliaciones": [{"titulo": "Una comparación", "aporta": "pon tu distrito junto a otro parecido y muestra en qué se diferencian."}, {"titulo": "Preguntas de los vecinos", "aporta": "recoge las dudas de cinco personas y comprueba si tu tablero las responde."}, {"titulo": "Datos que se actualizan", "aporta": "prepara el tablero para que se alimente solo cuando la fuente publique datos nuevos."}], "objetivos": ["Localizar fuentes públicas confiables sobre un territorio.", "Limpiar y combinar datos de varias fuentes.", "Elegir gráficos adecuados para cada pregunta.", "Redactar explicaciones claras para el público general.", "Verificar que el tablero responda a preguntas reales."], "habilidades": ["Datos abiertos y su licencia.", "Visualización de datos.", "Limpieza y combinación de tablas.", "Comunicación para el ciudadano.", "Pensamiento crítico sobre las fuentes."], "herramientas": ["Hoja de cálculo.", "Herramientas gratuitas de tableros y gráficos.", "Portales de datos abiertos."], "lineamientos": ["Cita siempre la fuente y la fecha de cada dato, y no publiques información que permita identificar a personas o viviendas concretas.", "Aclara las limitaciones: los datos públicos pueden estar desactualizados o ser incompletos."], "otroSector": "El mismo tablero puede construirse para un colegio, un hospital, un mercado o una empresa, siempre con datos que su propia institución haya hecho públicos."}$f69feca$::jsonb,27),
('reservas-laboratorios','tecnologia',array['negocios']::text[],'Reservar laboratorios y salas sin mandar mensajes','Explora cómo diseñar un sistema sencillo para ver qué espacios están libres, reservarlos y evitar cruces de horario.','Prototipo','~30 h',30,array['Software','Organización']::text[],array['crear','resolver','otro-sector']::text[],'ficticios','opcional','ingenieria de sistemas ingenieria de software ingenieria industrial ciberseguridad administracion estadistica computacion e informatica gestion administrativa levantamiento de requerimientos. diseno de interfaces sencillas. manejo de datos de horarios. diseno de reglas y excepciones. pruebas con usuarios. hoja de calculo. un formulario en linea. un lenguaje web si quieres ir mas lejos.',$fd61002${"id": "reservas-laboratorios", "area": "tecnologia", "areas2": ["negocios"], "titulo": "Reservar laboratorios y salas sin mandar mensajes", "resumen": "Explora cómo diseñar un sistema sencillo para ver qué espacios están libres, reservarlos y evitar cruces de horario.", "tipo": "Prototipo", "tiempo": "~30 h", "horas": 30, "etiquetas": ["Software", "Organización"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: usa espacios y horarios inventados; no guardes datos personales reales.", "prog": "opcional", "progTexto": "Programación opcional: puedes empezar sin programar y sumarla si quieres ir más lejos.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Ingeniería Industrial", "Ciberseguridad", "Administración", "Estadística", "Computación e Informática", "Gestión Administrativa"], "problema": ["Reservar un laboratorio o una sala suele depender de mensajes sueltos, hojas compartidas o ir a preguntar en persona, y los cruces de horario son frecuentes.", "Cuando varias personas piden el mismo espacio, nadie sabe quién llegó primero ni qué reglas se aplican, y el espacio termina vacío o con dos grupos esperando a la vez."], "desarrollar": ["Un prototipo con calendario por espacio, reservas por bloques de hora y un aviso cuando alguien intenta reservar algo ya ocupado. Puede ser una hoja de cálculo bien armada o una web sencilla.", "Empieza con un solo espacio y pocas reglas, y amplía solo cuando esas reglas funcionen. El resultado puede ser una hoja, un formulario o un prototipo navegable."], "ampliaciones": [{"titulo": "Reglas más finas", "aporta": "agrega límites de tiempo por persona, prioridades y cancelaciones con aviso."}, {"titulo": "Varios espacios", "aporta": "extiende el prototipo a diez espacios con equipamiento distinto, como laboratorio, sala de reuniones o taller."}, {"titulo": "Un reporte de uso", "aporta": "muestra qué espacios se usan más y cuáles quedan vacíos, para que quien los administre decida."}], "objetivos": ["Entender cómo se organiza hoy la reserva de un espacio real.", "Diseñar las reglas: quién reserva, por cuánto tiempo y cómo se cancela.", "Probar el prototipo tú o con alguien cercano y ajustar lo que no funcione.", "Detectar y evitar los cruces de horario.", "Documentar el uso de forma sencilla."], "habilidades": ["Levantamiento de requerimientos.", "Diseño de interfaces sencillas.", "Manejo de datos de horarios.", "Diseño de reglas y excepciones.", "Pruebas con usuarios."], "herramientas": ["Hoja de cálculo.", "Un formulario en línea.", "Un lenguaje web si quieres ir más lejos."], "lineamientos": ["Empieza con un solo espacio y pocas reglas. No guardes datos personales que no necesites.", "Pide permiso a quien administre el espacio antes de probarlo con otras personas."], "otroSector": "El mismo concepto sirve para reservar consultorios, canchas, talleres de un colegio o salas de reuniones de una pequeña empresa."}$fd61002$::jsonb,28),
('cuando-algo-sale-mal-seguir-un-incidente-y-medir-la-calidad-de-u','tecnologia',array['negocios']::text[],'Cuando algo sale mal: seguir un incidente y medir la calidad de un servicio','Diseña un sistema sencillo para registrar problemas de un servicio, seguirlos hasta resolverlos y medir si la atención mejora.','Prototipo','~30 h',30,array['Incidentes','Calidad de servicio','Procesos']::text[],array['crear','resolver','otro-sector']::text[],'ficticios','opcional','ingenieria de sistemas ingenieria de software ingenieria industrial administracion atencion al cliente computacion e informatica soporte tecnico gestion de incidentes. diseno de procesos. hoja de calculo avanzada. analisis de indicadores. visualizacion de datos. hoja de calculo o formulario en linea. herramienta de tableros. opcionalmente, una base de datos sencilla.',$f497009${"id": "cuando-algo-sale-mal-seguir-un-incidente-y-medir-la-calidad-de-u", "area": "tecnologia", "areas2": ["negocios"], "titulo": "Cuando algo sale mal: seguir un incidente y medir la calidad de un servicio", "resumen": "Diseña un sistema sencillo para registrar problemas de un servicio, seguirlos hasta resolverlos y medir si la atención mejora.", "tipo": "Prototipo", "tiempo": "~30 h", "horas": 30, "etiquetas": ["Incidentes", "Calidad de servicio", "Procesos"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: crea incidentes inventados, con su fecha, su gravedad y quién los atendió.", "prog": "opcional", "progTexto": "Programación opcional: puedes empezar sin programar y sumarla si quieres ir más lejos.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Ingeniería Industrial", "Administración", "Atención al Cliente", "Computación e Informática", "Soporte Técnico"], "problema": ["Cuando un servicio falla, el problema se reporta por mensajes sueltos, llamadas y correos. Nadie sabe cuántos hay abiertos, cuánto llevan esperando ni quién los atiende, y los mismos problemas reaparecen sin que se note.", "Sin registro no se puede medir la calidad: no se sabe si se atiende más rápido que el mes pasado ni qué tipo de problema es el más frecuente."], "desarrollar": ["Define los datos mínimos de un incidente: qué pasó, cuándo, qué tan grave es, quién lo atiende y cómo terminó. Diseña un flujo de estados, desde «recibido» hasta «cerrado», y un registro en una hoja o formulario. Carga 50 incidentes inventados.", "Calcula tres indicadores: cuánto tardó la primera respuesta, cuánto tardó la solución y cuántos casos se repiten. El resultado puede ser un tablero sencillo con esas cifras."], "ampliaciones": [{"titulo": "Prioridades", "aporta": "agrega reglas para atender primero lo más grave y mide el efecto."}, {"titulo": "Causas repetidas", "aporta": "agrupa los incidentes por causa y propone un cambio que evite los más comunes."}, {"titulo": "Satisfacción", "aporta": "suma una pregunta breve a quien reportó y relaciona la respuesta con el tiempo de atención."}], "objetivos": ["Definir los datos mínimos de un incidente.", "Diseñar el flujo de estados.", "Registrar incidentes y calcular indicadores.", "Identificar causas repetidas.", "Presentar los resultados en un tablero claro."], "habilidades": ["Gestión de incidentes.", "Diseño de procesos.", "Hoja de cálculo avanzada.", "Análisis de indicadores.", "Visualización de datos."], "herramientas": ["Hoja de cálculo o formulario en línea.", "Herramienta de tableros.", "Opcionalmente, una base de datos sencilla."], "lineamientos": ["Usa incidentes inventados. Si trabajas con un servicio real, pide permiso y quita datos personales.", "Mide pocos indicadores y explica cómo se calculan."], "otroSector": "El mismo sistema sirve para el mantenimiento de un edificio, las quejas de un restaurante, las averías de una flota o los reportes de un colegio."}$f497009$::jsonb,29),
('como-funciona-un-buscador-por-dentro','tecnologia',array['educacion']::text[],'¿Cómo funciona un buscador por dentro?','Construye un buscador mínimo sobre una colección pequeña de textos y descubre cómo decide qué resultado mostrar primero.','Prototipo','~30 h',30,array['Búsqueda','Algoritmos','Estructuras de datos']::text[],array['crear','resolver','otro-sector']::text[],'publicos','incluida','ingenieria de sistemas ingenieria de software computacion e informatica bibliotecologia ciencia de datos educacion analisis de sistemas estructuras de datos. procesamiento de texto. programacion basica. evaluacion de resultados. comunicacion tecnica. lenguaje de programacion sencillo. archivos de texto de practica. hoja de calculo para evaluar resultados.',$f0e43d5${"id": "como-funciona-un-buscador-por-dentro", "area": "tecnologia", "areas2": ["educacion"], "titulo": "¿Cómo funciona un buscador por dentro?", "resumen": "Construye un buscador mínimo sobre una colección pequeña de textos y descubre cómo decide qué resultado mostrar primero.", "tipo": "Prototipo", "tiempo": "~30 h", "horas": 30, "etiquetas": ["Búsqueda", "Algoritmos", "Estructuras de datos"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "publicos", "datosTexto": "públicos o propios: usa una colección pequeña de textos, como tus apuntes o artículos de libre acceso.", "prog": "incluida", "progTexto": "Incluye programación: puedes hacerlo con apoyo de una IA o en equipo.", "abordar": "solo, con una IA como apoyo, o en equipo con alguien que aporte lo que te falta (por ejemplo, una persona de Sistemas junto con otra que conozca bien el problema). Quien presente el proyecto debe poder explicar qué hace y comprobar que funciona.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Computación e Informática", "Bibliotecología", "Ciencia de Datos", "Educación", "Análisis de Sistemas"], "problema": ["Escribimos unas palabras y obtenemos resultados casi al instante, pero rara vez pensamos en cómo se decide qué documento va primero. Parece magia y en realidad se apoya en ideas sencillas: contar palabras y compararlas.", "Comprenderlas ayuda a buscar mejor, a entender por qué una búsqueda falla y a construir herramientas de búsqueda para colecciones propias."], "desarrollar": ["Reúne 30 a 50 textos cortos y construye un índice: una tabla que diga en qué documentos aparece cada palabra. Con eso programa una búsqueda que devuelva los documentos que contienen las palabras buscadas.", "Después mejora el orden con una regla simple, como dar más peso a las palabras raras, y compara los resultados antes y después. El resultado puede ser un buscador funcional con una explicación de cada paso."], "ampliaciones": [{"titulo": "Equivocarse al escribir", "aporta": "haz que el buscador tolere errores de ortografía."}, {"titulo": "Entender la intención", "aporta": "prueba cómo cambian los resultados si se buscan sinónimos."}, {"titulo": "Medir la calidad", "aporta": "evalúa con diez preguntas si el documento correcto aparece entre los primeros resultados."}], "objetivos": ["Construir un índice de palabras.", "Programar una búsqueda básica.", "Ordenar resultados con una regla razonable.", "Evaluar la calidad de los resultados.", "Explicar el funcionamiento sin tecnicismos."], "habilidades": ["Estructuras de datos.", "Procesamiento de texto.", "Programación básica.", "Evaluación de resultados.", "Comunicación técnica."], "herramientas": ["Lenguaje de programación sencillo.", "Archivos de texto de práctica.", "Hoja de cálculo para evaluar resultados."], "lineamientos": ["Usa textos que puedas compartir y cita sus fuentes.", "Mantén el sistema pequeño: la meta es entender el principio y no competir con un buscador real."], "otroSector": "La misma idea sirve para buscar dentro de las leyes, de los apuntes de un curso, del catálogo de una tienda o de las historias de un archivo."}$f0e43d5$::jsonb,30),
('como-hablan-dos-aplicaciones-entre-si','tecnologia','{}'::text[],'¿Cómo hablan dos aplicaciones entre sí?','Aprende cómo una aplicación le pide datos a otra a través de una interfaz pública, y úsala para armar algo útil.','Prototipo','~30 h',30,array['Integración','API','Automatización']::text[],array['crear','resolver']::text[],'publicos','incluida','ingenieria de sistemas ingenieria de software computacion e informatica analisis de sistemas estadistica administracion ciencia de datos conceptos de interfaces y servicios web. programacion basica. lectura de documentacion tecnica. manejo de datos estructurados. documentacion. lenguaje de programacion sencillo. herramientas para hacer consultas de prueba. hoja de calculo o pagina web para mostrar datos.',$f6afbd8${"id": "como-hablan-dos-aplicaciones-entre-si", "area": "tecnologia", "areas2": [], "titulo": "¿Cómo hablan dos aplicaciones entre sí?", "resumen": "Aprende cómo una aplicación le pide datos a otra a través de una interfaz pública, y úsala para armar algo útil.", "tipo": "Prototipo", "tiempo": "~30 h", "horas": 30, "etiquetas": ["Integración", "API", "Automatización"], "intencion": ["crear", "resolver"], "datos": "publicos", "datosTexto": "públicos: usa una interfaz pública y gratuita de datos, como la del clima, la de monedas o la de un portal de datos abiertos.", "prog": "incluida", "progTexto": "Incluye programación: puedes hacerlo con apoyo de una IA o en equipo.", "abordar": "solo, con una IA como apoyo, o en equipo con alguien que aporte lo que te falta (por ejemplo, una persona de Sistemas junto con otra que conozca bien el problema). Quien presente el proyecto debe poder explicar qué hace y comprobar que funciona.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Computación e Informática", "Análisis de Sistemas", "Estadística", "Administración", "Ciencia de Datos"], "problema": ["Casi todas las aplicaciones que usamos conversan con otras: el clima en el celular, el pago en una tienda, el mapa en una app de entregas. Esa conversación ocurre por interfaces que casi nadie ve.", "Quien entiende cómo funcionan puede conectar herramientas, automatizar tareas y construir cosas que antes exigían copiar y pegar a mano."], "desarrollar": ["Elige una interfaz pública y gratuita, lee su documentación y haz tu primera consulta a mano. Luego escribe un pequeño programa que pida los datos, los ordene y los muestre en una tabla o en una pantalla sencilla.", "Documenta lo que aprendiste, con un ejemplo de pedido y de respuesta, y los errores más comunes. El resultado puede ser un pequeño programa funcional y una guía para repetirlo con otra interfaz."], "ampliaciones": [{"titulo": "Datos que se actualizan", "aporta": "haz que tu programa se ejecute solo cada cierto tiempo."}, {"titulo": "Cuando algo falla", "aporta": "maneja los casos en que la interfaz no responde o devuelve un error."}, {"titulo": "Dos interfaces juntas", "aporta": "combina datos de dos fuentes distintas en una sola vista."}], "objetivos": ["Leer la documentación de una interfaz pública.", "Hacer consultas y comprender las respuestas.", "Programar un uso sencillo de los datos.", "Manejar errores comunes.", "Documentar el proceso paso a paso."], "habilidades": ["Conceptos de interfaces y servicios web.", "Programación básica.", "Lectura de documentación técnica.", "Manejo de datos estructurados.", "Documentación."], "herramientas": ["Lenguaje de programación sencillo.", "Herramientas para hacer consultas de prueba.", "Hoja de cálculo o página web para mostrar datos."], "lineamientos": ["Respeta los límites de uso de la interfaz y no hagas consultas masivas.", "Cuidados: no publiques tus claves de acceso: guárdalas fuera del código que compartas."], "otroSector": "La misma habilidad sirve para conectar una hoja con un correo, un formulario con un calendario, una tienda con una hoja de pedidos o un sensor con un tablero."}$f6afbd8$::jsonb,31),
('que-tarea-hace-que-tu-computadora-gaste-mas-energia','tecnologia',array['ambiente']::text[],'¿Qué tarea hace que tu computadora gaste más energía?','Investiga cómo cambia el consumo energético de una computadora según las tareas que realiza, las configuraciones utilizadas y el tiempo de uso. Descubre qué factores tienen un mayor impacto en el consumo eléctrico y cómo pequeñas decisiones pueden influir en el gasto acumulado a lo largo del tiempo.','Investigación','2 semanas a 2 meses',32,array['Tecnología','Eficiencia energética','Análisis de datos']::text[],array['investigar','otro-sector']::text[],'propios','opcional','ingenieria de sistemas ingenieria electrica ingenieria electronica ingenieria ambiental ingenieria industrial fisica ciencia de datos economia recoleccion de datos. analisis de informacion tecnica. interpretacion de graficos. calculos de energia y costos. pensamiento critico. comunicacion de resultados. computadora. hoja de calculo. medidor de consumo electrico (opcional). herramientas de monitoreo del sistema. calculadoras de costos energeticos.',$f999661${"id": "que-tarea-hace-que-tu-computadora-gaste-mas-energia", "area": "tecnologia", "areas2": ["ambiente"], "titulo": "¿Qué tarea hace que tu computadora gaste más energía?", "resumen": "Investiga cómo cambia el consumo energético de una computadora según las tareas que realiza, las configuraciones utilizadas y el tiempo de uso. Descubre qué factores tienen un mayor impacto en el consumo eléctrico y cómo pequeñas decisiones pueden influir en el gasto acumulado a lo largo del tiempo.", "tipo": "Investigación", "tiempo": "2 semanas a 2 meses", "horas": 32, "etiquetas": ["Tecnología", "Eficiencia energética", "Análisis de datos"], "intencion": ["investigar", "otro-sector"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes. Si no dispones de un medidor de consumo, puedes trabajar con estimaciones basadas en especificaciones técnicas y fuentes públicas.", "prog": "opcional", "progTexto": "Programación opcional: puedes empezar sin programar y sumarla si quieres ir más lejos.", "carreras": ["Ingeniería de Sistemas", "Ingeniería Eléctrica", "Ingeniería Electrónica", "Ingeniería Ambiental", "Ingeniería Industrial", "Física", "Ciencia de Datos", "Economía"], "problema": ["Las computadoras forman parte de la vida diaria de millones de personas. Se utilizan para estudiar, trabajar, comunicarse, entretenerse y desarrollar proyectos. Sin embargo, pocas veces se analiza cuánto cambia el consumo energético dependiendo de la actividad que se esté realizando.", "Una computadora en reposo no consume lo mismo que una utilizada para editar video, ejecutar videojuegos o procesar grandes cantidades de datos. Del mismo modo, configuraciones como el brillo de la pantalla, los tiempos de suspensión o los periféricos conectados también pueden influir en el consumo total.", "Aunque estas diferencias pueden parecer pequeñas a simple vista, al acumularse durante semanas o meses pueden representar un impacto significativo tanto en el gasto económico como en el uso eficiente de la energía."], "desarrollar": ["Investiga el consumo de una computadora en distintos escenarios de uso y registra los resultados de forma organizada.", "Por ejemplo:", {"lista": ["Reposo o inactividad.", "Navegación web.", "Reproducción de video.", "Trabajo de oficina.", "Desarrollo de software.", "Uso intensivo del procesador o la tarjeta gráfica."]}, "Presenta la información mediante tablas, gráficos o comparaciones visuales que permitan identificar las diferencias entre cada situación."], "ampliaciones": [{"titulo": "Comparar equipos", "aporta": "analiza cómo cambia el consumo entre una computadora portátil, una computadora de escritorio u otros dispositivos similares."}, {"titulo": "Proyectar escenarios", "aporta": "estima cuánto consumiría un equipo durante un mes o un año según distintos hábitos de uso."}, {"titulo": "Evaluar configuraciones", "aporta": "compara el efecto de modificar parámetros como el brillo de la pantalla, los planes de energía o los tiempos de suspensión."}], "objetivos": ["Definir escenarios de uso comparables.", "Obtener o estimar valores de consumo energético.", "Organizar y visualizar la información recopilada.", "Comparar distintos patrones de uso.", "Explicar las diferencias observadas y sus posibles causas."], "habilidades": ["Recolección de datos.", "Análisis de información técnica.", "Interpretación de gráficos.", "Cálculos de energía y costos.", "Pensamiento crítico.", "Comunicación de resultados."], "herramientas": ["Computadora.", "Hoja de cálculo.", "Medidor de consumo eléctrico (opcional).", "Herramientas de monitoreo del sistema.", "Calculadoras de costos energéticos."], "lineamientos": ["No abras ni manipules componentes eléctricos para realizar mediciones. Si no dispones de instrumentos de medición directa, indica claramente cuándo los valores utilizados corresponden a estimaciones.", "Diferencia correctamente conceptos como potencia eléctrica, energía consumida y costo económico, ya que representan magnitudes distintas.", "Documenta las condiciones de cada prueba para que los resultados puedan interpretarse correctamente."], "otroSector": "La misma metodología puede aplicarse al análisis de electrodomésticos, equipos de oficina, sistemas de iluminación, servidores, herramientas industriales o cualquier dispositivo que utilice energía eléctrica."}$f999661$::jsonb,32),
('que-sabe-una-aplicacion-sobre-sus-usuarios','tecnologia',array['derecho']::text[],'¿Qué sabe una aplicación sobre sus usuarios?','Imagina qué información afirma recopilar una aplicación, cómo explica el uso de esos datos y qué tan fácil resulta para una persona comprender las implicaciones de aceptar determinados permisos. Descubre cómo traducir documentos extensos y complejos en información clara y comprensible para usuarios comunes.','Análisis','2 semanas a 2 meses',32,array['Privacidad','Seguridad digital','Análisis de información']::text[],array['investigar','resolver','otro-sector']::text[],'publicos','sin','ingenieria de sistemas ciberseguridad ingenieria de software derecho comunicaciones administracion ciencia de datos economia diseno ux lectura critica. privacidad digital. organizacion de informacion. analisis documental. comunicacion visual. pensamiento critico. navegador web. documentacion oficial. hoja de calculo. herramientas de diseno o presentaciones. aplicaciones para elaborar infografias.',$f2f6d7a${"id": "que-sabe-una-aplicacion-sobre-sus-usuarios", "area": "tecnologia", "areas2": ["derecho"], "titulo": "¿Qué sabe una aplicación sobre sus usuarios?", "resumen": "Imagina qué información afirma recopilar una aplicación, cómo explica el uso de esos datos y qué tan fácil resulta para una persona comprender las implicaciones de aceptar determinados permisos. Descubre cómo traducir documentos extensos y complejos en información clara y comprensible para usuarios comunes.", "tipo": "Análisis", "tiempo": "2 semanas a 2 meses", "horas": 32, "etiquetas": ["Privacidad", "Seguridad digital", "Análisis de información"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "publicos", "datosTexto": "públicos: puedes revisar políticas de privacidad, condiciones de uso, permisos declarados y documentación oficial disponible públicamente.", "prog": "sin", "progTexto": "Sin programación: se puede hacer completo con documentos y hoja de cálculo.", "carreras": ["Ingeniería de Sistemas", "Ciberseguridad", "Ingeniería de Software", "Derecho", "Comunicaciones", "Administración", "Ciencia de Datos", "Economía", "Diseño UX"], "problema": ["Cada día millones de personas instalan aplicaciones en sus teléfonos, computadoras y otros dispositivos. Durante ese proceso suelen aceptar permisos, condiciones de uso y políticas de privacidad sin leerlas completamente o sin comprender qué significan muchos de sus términos.", "Aunque las empresas suelen publicar información sobre los datos que recopilan y cómo los utilizan, estos documentos pueden resultar largos, técnicos o difíciles de interpretar para alguien sin conocimientos especializados. Como consecuencia, muchas personas desconocen qué información comparten, durante cuánto tiempo podría conservarse o con qué finalidades se utiliza.", "Comprender cómo una aplicación describe sus prácticas de privacidad permite desarrollar una visión más crítica sobre el uso de los datos personales y ayuda a tomar decisiones mejor informadas antes de utilizar un servicio digital."], "desarrollar": ["Selecciona una aplicación conocida y revisa la información pública disponible relacionada con privacidad y uso de datos.", "Por ejemplo:", {"lista": ["Política de privacidad.", "Condiciones de uso.", "Permisos solicitados.", "Información mostrada en tiendas de aplicaciones.", "Documentación oficial disponible."]}, "Organiza los hallazgos en una ficha o informe visual que explique qué categorías de datos se mencionan, cuáles son las finalidades declaradas y qué aspectos podrían resultar difíciles de comprender para un usuario promedio."], "ampliaciones": [{"titulo": "Comparar aplicaciones similares", "aporta": "analiza cómo dos servicios que ofrecen funciones parecidas explican el uso de los datos de sus usuarios."}, {"titulo": "Traducir información compleja", "aporta": "transforma documentos extensos en resúmenes visuales fáciles de comprender."}, {"titulo": "Analizar permisos", "aporta": "compara los permisos solicitados por una aplicación con las funciones que ofrece para entender por qué podrían ser necesarios."}], "objetivos": ["Localizar y revisar documentación pública relacionada con privacidad.", "Identificar categorías de datos mencionadas por la aplicación.", "Analizar cómo se comunican las finalidades del uso de esos datos.", "Organizar la información de forma clara y accesible.", "Elaborar conclusiones basadas en información verificable."], "habilidades": ["Lectura crítica.", "Privacidad digital.", "Organización de información.", "Análisis documental.", "Comunicación visual.", "Pensamiento crítico."], "herramientas": ["Navegador web.", "Documentación oficial.", "Hoja de cálculo.", "Herramientas de diseño o presentaciones.", "Aplicaciones para elaborar infografías."], "lineamientos": ["Basa todas las conclusiones en información verificable procedente de fuentes oficiales o documentación pública. No afirmes que una aplicación recopila información que no esté documentada o respaldada por las fuentes consultadas.", "No intentes interceptar comunicaciones, analizar tráfico privado ni acceder a información que no sea pública. El objetivo del proyecto es comprender y comunicar mejor la información que los propios proveedores del servicio ponen a disposición de los usuarios.", "Diferencia claramente entre hechos documentados, interpretaciones personales y aspectos que no puedan determinarse a partir de la información disponible."], "otroSector": "La misma metodología puede aplicarse al análisis de plataformas educativas, servicios financieros, dispositivos inteligentes, redes sociales, sitios de comercio electrónico, aplicaciones de salud o herramientas de productividad."}$f2f6d7a$::jsonb,33),
('como-explica-sus-decisiones-una-inteligencia-artificial-sencilla','tecnologia',array['ciencias']::text[],'¿Cómo explica sus decisiones una inteligencia artificial sencilla?','Entrena un modelo sencillo que se pueda explicar y comprueba si las razones que da son coherentes con lo que ocurre en los datos.','Investigación','1 a 2 meses',39,array['Inteligencia artificial','Explicabilidad','Ciencia de datos']::text[],array['investigar','otro-sector']::text[],'publicos','incluida','ingenieria de sistemas ingenieria de software inteligencia artificial ciencia de datos estadistica matematica derecho computacion e informatica aprendizaje automatico basico. programacion en un lenguaje de datos. analisis e interpretacion de resultados. pensamiento critico sobre la ia. comunicacion tecnica. lenguaje de programacion para datos y sus bibliotecas de analisis. cuaderno interactivo. conjuntos de datos publicos.',$fb98ab5${"id": "como-explica-sus-decisiones-una-inteligencia-artificial-sencilla", "area": "tecnologia", "areas2": ["ciencias"], "titulo": "¿Cómo explica sus decisiones una inteligencia artificial sencilla?", "resumen": "Entrena un modelo sencillo que se pueda explicar y comprueba si las razones que da son coherentes con lo que ocurre en los datos.", "tipo": "Investigación", "tiempo": "1 a 2 meses", "horas": 39, "etiquetas": ["Inteligencia artificial", "Explicabilidad", "Ciencia de datos"], "intencion": ["investigar", "otro-sector"], "datos": "publicos", "datosTexto": "públicos: usa un conjunto de datos abierto y conocido para un problema de clasificación, como el de una encuesta o el de características de plantas.", "prog": "incluida", "progTexto": "Incluye programación: puedes hacerlo con apoyo de una IA o en equipo.", "abordar": "con una IA como apoyo para escribir el código del modelo, o en equipo con alguien de Sistemas o Ciencia de Datos. Lo importante es que entiendas por qué el modelo decide lo que decide y lo puedas explicar.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Inteligencia Artificial", "Ciencia de Datos", "Estadística", "Matemática", "Derecho", "Computación e Informática"], "problema": ["Cuando un sistema automático decide algo, como aprobar una solicitud o clasificar un reclamo, a menudo nadie sabe explicar por qué. Cuanto más complejo es el modelo, más difícil se hace dar una razón que una persona pueda revisar.", "Sin una explicación, no se pueden detectar errores ni reclamos injustos, y las personas afectadas no tienen cómo cuestionar la decisión."], "desarrollar": ["Elige un conjunto de datos abierto y entrena un modelo sencillo, como un árbol de decisión, que se pueda leer como una serie de preguntas. Muestra qué variables pesan más y cómo se llega a una respuesta en tres o cuatro casos concretos.", "Compara esa explicación con tu conocimiento del problema: ¿tiene sentido? ¿Hay alguna razón sospechosa? El resultado puede ser un informe con los casos explicados paso a paso y un resumen de lo que se aprendió sobre los límites de la explicación."], "ampliaciones": [{"titulo": "Dos modelos", "aporta": "compara un modelo fácil de explicar con otro más preciso y pregúntate cuánto vale la precisión si no se puede explicar."}, {"titulo": "Caso de error", "aporta": "busca un caso en que el modelo se equivoca y explica por qué."}, {"titulo": "Una explicación para el usuario", "aporta": "redacta cómo le contarías la decisión a la persona afectada con palabras sencillas."}], "objetivos": ["Entrenar un modelo sencillo y comprender su funcionamiento.", "Identificar las variables que más influyen en sus decisiones.", "Explicar casos individuales con un lenguaje claro.", "Contrastar la explicación con el conocimiento del problema.", "Reconocer los límites de explicar modelos más complejos."], "habilidades": ["Aprendizaje automático básico.", "Programación en un lenguaje de datos.", "Análisis e interpretación de resultados.", "Pensamiento crítico sobre la IA.", "Comunicación técnica."], "herramientas": ["Lenguaje de programación para datos y sus bibliotecas de análisis.", "Cuaderno interactivo.", "Conjuntos de datos públicos."], "lineamientos": ["No afirmes que una IA «razona»: describe qué variables usa y qué reglas se pueden leer en el modelo.", "Cuidados: usa datos públicos que no identifiquen a personas, y evita casos sensibles como salud o antecedentes personales."], "otroSector": "La misma pregunta, «¿por qué decidió esto?», se aplica a decisiones sobre créditos, becas, selección de personal, diagnóstico de fallas y recomendaciones de contenido."}$fb98ab5$::jsonb,34),
('que-pasa-cuando-los-datos-crecen-diez-veces','tecnologia',array['ciencias']::text[],'¿Qué pasa cuando los datos crecen diez veces?','Mide cómo cambia el tiempo de una búsqueda, un ordenamiento o una consulta cuando la cantidad de datos se multiplica.','Investigación','1 a 2 meses',39,array['Escalabilidad','Bases de datos','Algoritmos']::text[],array['investigar','otro-sector']::text[],'ficticios','incluida','ingenieria de sistemas ingenieria de software computacion e informatica ciencia de datos matematica estadistica analisis de sistemas bases de datos e indices. complejidad de algoritmos. programacion en un lenguaje de datos. medicion y analisis de resultados. comunicacion tecnica. un gestor de bases de datos gratuito. lenguaje de programacion con herramientas de medicion. hoja de calculo para graficar.',$f86a768${"id": "que-pasa-cuando-los-datos-crecen-diez-veces", "area": "tecnologia", "areas2": ["ciencias"], "titulo": "¿Qué pasa cuando los datos crecen diez veces?", "resumen": "Mide cómo cambia el tiempo de una búsqueda, un ordenamiento o una consulta cuando la cantidad de datos se multiplica.", "tipo": "Investigación", "tiempo": "1 a 2 meses", "horas": 39, "etiquetas": ["Escalabilidad", "Bases de datos", "Algoritmos"], "intencion": ["investigar", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: genera tablas con datos inventados, cada vez más grandes, para probar.", "prog": "incluida", "progTexto": "Incluye programación: puedes hacerlo con apoyo de una IA o en equipo.", "abordar": "solo, con una IA como apoyo, o en equipo con alguien que aporte lo que te falta (por ejemplo, una persona de Sistemas junto con otra que conozca bien el problema). Quien presente el proyecto debe poder explicar qué hace y comprobar que funciona.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Computación e Informática", "Ciencia de Datos", "Matemática", "Estadística", "Análisis de Sistemas"], "problema": ["Un programa o una base de datos puede funcionar perfecto con cien registros y volverse inusable con un millón. Casi siempre se descubre cuando el sistema ya está en uso y los clientes se quejan.", "Lo difícil es que el tiempo no siempre crece en proporción: a veces se multiplica por diez y a veces por cien, según cómo esté hecho."], "desarrollar": ["Genera tablas de datos ficticios de 1000, 10 000, 100 000 y un millón de filas. Mide cuánto tardan tres operaciones comunes, como buscar un dato, ordenar y contar repeticiones, con y sin una estructura que ayude, como un índice.", "Grafica cómo crece el tiempo con el tamaño y compara las operaciones. El resultado puede ser un informe con gráficos y una recomendación sobre cuándo vale la pena agregar un índice o cambiar de estrategia."], "ampliaciones": [{"titulo": "Un algoritmo mejor", "aporta": "reemplaza una búsqueda lenta por otra más inteligente y mide cuánto mejora a medida que crecen los datos."}, {"titulo": "Lo que cuesta el índice", "aporta": "mide cuánto espacio y cuánto tiempo de escritura agrega cada mejora."}, {"titulo": "El punto de quiebre", "aporta": "estima cuántos datos aguantaría tu solución antes de dejar de ser aceptable."}], "objetivos": ["Generar conjuntos de datos de tamaño creciente.", "Medir tiempos de operaciones comunes.", "Comparar el crecimiento del tiempo con y sin mejoras.", "Interpretar los resultados con gráficos.", "Recomendar cuándo conviene optimizar."], "habilidades": ["Bases de datos e índices.", "Complejidad de algoritmos.", "Programación en un lenguaje de datos.", "Medición y análisis de resultados.", "Comunicación técnica."], "herramientas": ["Un gestor de bases de datos gratuito.", "Lenguaje de programación con herramientas de medición.", "Hoja de cálculo para graficar."], "lineamientos": ["Repite cada medición varias veces y usa el promedio: un solo resultado puede engañar.", "Documenta tu computadora y tus supuestos: los tiempos cambian con el equipo."], "otroSector": "La misma pregunta se aplica a un almacén que crece, a una lista de clientes que se multiplica o a un archivo de documentos que pasa de cien a diez mil."}$f86a768$::jsonb,35),
('de-la-foto-de-una-factura-al-dato-en-una-tabla','tecnologia',array['negocios']::text[],'De la foto de una factura al dato en una tabla','Diseña un proceso que lea la foto de una factura, extraiga los datos importantes y los pase a una tabla, midiendo cuántos errores comete.','Prototipo','1 a 2 meses',39,array['Automatización','Reconocimiento de texto','Documentos']::text[],array['crear','resolver','otro-sector']::text[],'ficticios','incluida','ingenieria de sistemas ingenieria de software contabilidad administracion computacion e informatica archivistica secretariado auditoria reconocimiento optico de texto. programacion basica o automatizacion. evaluacion de precision. diseno de procesos. conocimientos contables basicos. herramientas de lectura de texto en imagenes. hoja de calculo. lenguaje de programacion o herramientas de automatizacion.',$f6ede7d${"id": "de-la-foto-de-una-factura-al-dato-en-una-tabla", "area": "tecnologia", "areas2": ["negocios"], "titulo": "De la foto de una factura al dato en una tabla", "resumen": "Diseña un proceso que lea la foto de una factura, extraiga los datos importantes y los pase a una tabla, midiendo cuántos errores comete.", "tipo": "Prototipo", "tiempo": "1 a 2 meses", "horas": 39, "etiquetas": ["Automatización", "Reconocimiento de texto", "Documentos"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: inventa o diseña 30 a 50 facturas o recibos de práctica; no uses documentos reales de nadie.", "prog": "incluida", "progTexto": "Incluye programación: puedes hacerlo con apoyo de una IA o en equipo.", "abordar": "solo, con una IA como apoyo, o en equipo con alguien que aporte lo que te falta (por ejemplo, una persona de Sistemas junto con otra que conozca bien el problema). Quien presente el proyecto debe poder explicar qué hace y comprobar que funciona.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Contabilidad", "Administración", "Computación e Informática", "Archivística", "Secretariado", "Auditoría"], "problema": ["En muchos negocios las facturas, boletas y recibos se pasan a mano a una hoja de cálculo. Es lento y se cometen errores: un monto con un dígito cambiado o una fecha mal escrita pueden descuadrar un mes completo.", "Existen herramientas que leen texto desde una imagen, pero sus resultados varían según la calidad de la foto, la letra y el formato del documento, y casi nunca se mide cuánto fallan."], "desarrollar": ["Prepara 30 a 50 facturas ficticias con distintos formatos y calidades de foto, y registra a mano los datos correctos: fecha, proveedor, monto y detalle. Usa una herramienta de lectura de texto para extraerlos y compara con lo correcto.", "Mide qué porcentaje se leyó bien en cada campo y qué tipo de errores aparecen. El resultado puede ser un proceso que lleve los datos a una tabla, con una revisión humana de los casos dudosos y un informe de precisión."], "ampliaciones": [{"titulo": "Detectar lo dudoso", "aporta": "agrega reglas que marquen para revisión los montos raros o los campos vacíos."}, {"titulo": "Mejorar la foto", "aporta": "prueba qué cambia con una foto mejor iluminada o recortada antes de leerla."}, {"titulo": "Distintos formatos", "aporta": "prueba con facturas de varios proveedores y estudia cómo adaptar el proceso."}], "objetivos": ["Preparar un conjunto de facturas ficticias con respuesta conocida.", "Aplicar una herramienta de lectura de texto.", "Medir precisión por campo.", "Diseñar una revisión humana de los casos dudosos.", "Cargar los datos a una tabla ordenada."], "habilidades": ["Reconocimiento óptico de texto.", "Programación básica o automatización.", "Evaluación de precisión.", "Diseño de procesos.", "Conocimientos contables básicos."], "herramientas": ["Herramientas de lectura de texto en imágenes.", "Hoja de cálculo.", "Lenguaje de programación o herramientas de automatización."], "lineamientos": ["Cuidados: usa solo facturas ficticias o propias. Las facturas reales de un negocio o de otras personas contienen datos que no debes subir a servicios externos.", "Mantén siempre una revisión humana antes de usar los datos para algo importante."], "otroSector": "El mismo proceso sirve para leer recetas médicas de práctica, formularios de una encuesta en papel, documentos de un archivo histórico o recibos de un negocio familiar."}$f6ede7d$::jsonb,36),
('del-excel-que-todos-usan-al-sistema-que-nadie-rompe','tecnologia',array['negocios']::text[],'Del Excel que todos usan al sistema que nadie rompe','Toma una hoja de cálculo que ya se volvió inmanejable y conviértela en un sistema más ordenado y seguro, paso a paso.','Prototipo','1 a 2 meses',39,array['Hojas de cálculo','Bases de datos','Procesos']::text[],array['crear','resolver','otro-sector']::text[],'ficticios','opcional','ingenieria de sistemas ingenieria de software contabilidad administracion ingenieria industrial computacion e informatica secretariado hojas de calculo avanzadas. modelado de datos basico. gestion de cambios. analisis de riesgos. redaccion de guias. hoja de calculo. formularios en linea. opcionalmente un gestor de bases de datos.',$f5c516d${"id": "del-excel-que-todos-usan-al-sistema-que-nadie-rompe", "area": "tecnologia", "areas2": ["negocios"], "titulo": "Del Excel que todos usan al sistema que nadie rompe", "resumen": "Toma una hoja de cálculo que ya se volvió inmanejable y conviértela en un sistema más ordenado y seguro, paso a paso.", "tipo": "Prototipo", "tiempo": "1 a 2 meses", "horas": 39, "etiquetas": ["Hojas de cálculo", "Bases de datos", "Procesos"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: crea una hoja con datos inventados de un negocio pequeño.", "prog": "opcional", "progTexto": "Programación opcional: puedes empezar sin programar y sumarla si quieres ir más lejos.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Contabilidad", "Administración", "Ingeniería Industrial", "Computación e Informática", "Secretariado"], "problema": ["En casi todos los negocios hay una hoja de cálculo que «todos usan». Con los meses crece, se llena de fórmulas frágiles, de datos repetidos y de versiones, y basta que alguien borre una columna para que todo deje de funcionar.", "Pasar a un sistema real da miedo por el costo y la complejidad, y se posterga hasta que ocurre un error caro."], "desarrollar": ["Elige o crea una hoja de un negocio ficticio con 500 a 1000 filas y varios problemas: datos repetidos, fórmulas copiadas y campos libres. Haz una lista de sus riesgos y una de lo que el negocio necesita realmente hacer con ella.", "Reorganiza los datos en tablas separadas, protege las fórmulas y crea un formulario de ingreso. Compara las dos versiones según los errores que se evitan. El resultado puede ser la hoja mejorada y una guía de migración."], "ampliaciones": [{"titulo": "Una base de datos", "aporta": "pasa los datos a una base real y compara qué se gana y qué se complica."}, {"titulo": "Roles y permisos", "aporta": "define quién puede editar y quién solo mirar, y cómo se registra cada cambio."}, {"titulo": "Copias de respaldo", "aporta": "agrega una rutina automática de copia y pruébala recuperando un archivo."}], "objetivos": ["Diagnosticar los riesgos de una hoja de cálculo.", "Reorganizar los datos para evitar repeticiones.", "Proteger fórmulas y limitar la edición.", "Comparar la versión antigua y la nueva.", "Redactar una guía de migración."], "habilidades": ["Hojas de cálculo avanzadas.", "Modelado de datos básico.", "Gestión de cambios.", "Análisis de riesgos.", "Redacción de guías."], "herramientas": ["Hoja de cálculo.", "Formularios en línea.", "Opcionalmente un gestor de bases de datos."], "lineamientos": ["Trabaja con datos ficticios y haz una copia antes de cada cambio grande.", "Si lo pruebas con un negocio real, pide permiso y explica los riesgos de cualquier cambio."], "otroSector": "La misma migración sirve para listas de socios, inventarios de un taller, controles de asistencia, pedidos de un restaurante y hojas de pagos de una asociación."}$f5c516d$::jsonb,37),
('un-simulador-de-filas-de-espera','tecnologia',array['industria']::text[],'Un simulador de filas de espera','Explora cómo pequeños cambios en la organización de un servicio pueden afectar significativamente el tiempo que las personas esperan para ser atendidas. Descubre cómo modelar llegadas, atenciones y recursos disponibles para analizar distintos escenarios sin necesidad de intervenir en un entorno real.','Simulación','2 semanas a 3 meses',45,array['Modelamiento','Procesos','Simulación']::text[],array['crear','investigar','otro-sector']::text[],'ficticios','opcional','ingenieria de sistemas ingenieria industrial ingenieria de software matematica estadistica economia investigacion operativa ciencia de datos modelamiento de sistemas. pensamiento logico. simulacion de procesos. estadistica basica. analisis de datos. programacion o modelamiento con hojas de calculo. hoja de calculo. lenguaje de programacion (opcional). herramientas de visualizacion. diagramas de flujo. software de simulacion (opcional).',$f597d95${"id": "un-simulador-de-filas-de-espera", "area": "tecnologia", "areas2": ["industria"], "titulo": "Un simulador de filas de espera", "resumen": "Explora cómo pequeños cambios en la organización de un servicio pueden afectar significativamente el tiempo que las personas esperan para ser atendidas. Descubre cómo modelar llegadas, atenciones y recursos disponibles para analizar distintos escenarios sin necesidad de intervenir en un entorno real.", "tipo": "Simulación", "tiempo": "2 semanas a 3 meses", "horas": 45, "etiquetas": ["Modelamiento", "Procesos", "Simulación"], "intencion": ["crear", "investigar", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: puedes hacerlo sin pedir permiso a nadie.", "prog": "opcional", "progTexto": "Programación opcional: puedes empezar sin programar y sumarla si quieres ir más lejos.", "carreras": ["Ingeniería de Sistemas", "Ingeniería Industrial", "Ingeniería de Software", "Matemática", "Estadística", "Economía", "Investigación Operativa", "Ciencia de Datos"], "problema": ["Las filas de espera forman parte de muchas actividades cotidianas. Aparecen en cafeterías, bancos, supermercados, hospitales, centros de atención, aeropuertos y numerosos servicios donde varias personas necesitan acceder a recursos limitados.", "Cuando una fila se vuelve demasiado larga, suele asumirse que el problema es la falta de personal o la alta demanda. Sin embargo, la situación puede ser mucho más compleja. Factores como la organización de las filas, la duración promedio de cada atención, la variabilidad en la llegada de personas o la distribución de recursos pueden influir notablemente en los tiempos de espera.", "Tomar decisiones sin comprender estos factores puede generar inversiones innecesarias o soluciones que no resuelven el problema real. La simulación permite experimentar con distintos escenarios antes de aplicar cambios en la práctica."], "desarrollar": ["Construye un simulador sencillo donde las personas lleguen a una fila, esperen su turno y sean atendidas por una o varias ventanillas.", "El modelo puede permitir modificar variables como:", {"lista": ["Número de personas que llegan.", "Tiempo promedio de atención.", "Cantidad de ventanillas disponibles.", "Horario de funcionamiento.", "Organización de las filas."]}, "A partir de estos parámetros, analiza indicadores como tiempo promedio de espera, tamaño de las filas o utilización de los recursos disponibles."], "ampliaciones": [{"titulo": "Comparar organizaciones", "aporta": "analiza las diferencias entre una fila única compartida y varias filas independientes."}, {"titulo": "Simular horas punta", "aporta": "incorpora periodos donde la llegada de personas aumenta considerablemente."}, {"titulo": "Visualizar el comportamiento", "aporta": "crea gráficos o animaciones que muestren cómo crece y disminuye la fila a lo largo del tiempo."}], "objetivos": ["Comprender los elementos básicos de un sistema de espera.", "Definir reglas para las llegadas y atenciones.", "Construir un modelo de simulación funcional.", "Comparar distintos escenarios y configuraciones.", "Interpretar los resultados obtenidos y justificar conclusiones."], "habilidades": ["Modelamiento de sistemas.", "Pensamiento lógico.", "Simulación de procesos.", "Estadística básica.", "Análisis de datos.", "Programación o modelamiento con hojas de cálculo."], "herramientas": ["Hoja de cálculo.", "Lenguaje de programación (opcional).", "Herramientas de visualización.", "Diagramas de flujo.", "Software de simulación (opcional)."], "lineamientos": ["Utiliza parámetros ficticios o claramente identificados como estimaciones. Documenta las reglas de funcionamiento del modelo y explica las simplificaciones realizadas.", "Recuerda que una simulación representa un escenario controlado y no necesariamente reproduce todas las condiciones de un sistema real. Las conclusiones deben interpretarse dentro de los supuestos definidos para el modelo."], "otroSector": "La misma metodología puede aplicarse para estudiar la atención en hospitales, cajas de supermercados, restaurantes, bancos, procesos industriales, sistemas de transporte, centros logísticos o plataformas digitales que gestionan solicitudes de usuarios."}$f597d95$::jsonb,38),
('tareas-de-oficina-que-se-hacen-solas','tecnologia',array['negocios']::text[],'Tareas de oficina que se hacen solas','Descubre cómo identificar actividades repetitivas que consumen tiempo y diseñar una solución que ayude a realizarlas de forma más rápida, organizada y consistente.','Prototipo','1 a 3 meses',52,array['Automatización','Productividad','Procesos']::text[],array['crear','resolver','otro-sector']::text[],'ficticios','opcional','ingenieria de sistemas ingenieria industrial administracion ciencia de datos contabilidad economia logistica emprendimiento analisis de procesos. automatizacion basica. diseno de flujos de trabajo. organizacion de informacion. resolucion de problemas. pensamiento sistemico. hojas de calculo. formularios digitales. herramientas de automatizacion. bases de datos sencillas. aplicaciones web o moviles si deseas ampliar el proyecto. diagramas de flujo.',$f88a7d9${"id": "tareas-de-oficina-que-se-hacen-solas", "area": "tecnologia", "areas2": ["negocios"], "titulo": "Tareas de oficina que se hacen solas", "resumen": "Descubre cómo identificar actividades repetitivas que consumen tiempo y diseñar una solución que ayude a realizarlas de forma más rápida, organizada y consistente.", "tipo": "Prototipo", "tiempo": "1 a 3 meses", "horas": 52, "etiquetas": ["Automatización", "Productividad", "Procesos"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios o propios: puedes trabajar con procesos simulados o inspirarte en tareas reales de una oficina, negocio familiar, asociación o emprendimiento.", "prog": "opcional", "progTexto": "Programación opcional: puedes empezar sin programar y sumarla si quieres ir más lejos.", "carreras": ["Ingeniería de Sistemas", "Ingeniería Industrial", "Administración", "Ciencia de Datos", "Contabilidad", "Economía", "Logística", "Emprendimiento"], "problema": ["En muchas oficinas y pequeños negocios existen tareas que se repiten todos los días: registrar información, copiar datos entre documentos, enviar mensajes similares, actualizar listas, generar reportes o verificar estados de pedidos.", "Aunque cada acción individual puede tomar apenas unos minutos, la suma de estas actividades representa una cantidad considerable de tiempo a lo largo de semanas y meses.", "Además, los procesos manuales suelen generar errores cuando una persona olvida un paso, transcribe mal un dato o utiliza una versión desactualizada de un documento. A medida que aumenta el trabajo, estos pequeños errores pueden multiplicarse y afectar la calidad del servicio o la eficiencia del equipo.", "La automatización no busca reemplazar a las personas, sino permitir que dediquen más tiempo a actividades que requieren criterio, comunicación o creatividad."], "desarrollar": ["Selecciona un proceso sencillo compuesto por varias tareas repetitivas.", "Por ejemplo:", {"lista": ["Registrar pedidos recibidos por mensaje.", "Generar reportes semanales.", "Actualizar inventarios.", "Organizar solicitudes de clientes.", "Gestionar inscripciones a una actividad."]}, "A partir de ello, diseña una solución que reduzca pasos manuales mediante formularios, hojas de cálculo inteligentes, plantillas automatizadas o una aplicación sencilla."], "ampliaciones": [{"titulo": "Un registro de lo que ahorraste", "aporta": "mide cuántos minutos por semana libera cada tarea automatizada y cuáles valen la pena."}, {"titulo": "Cuando la tarea cambia", "aporta": "prueba qué pasa si cambia el formato de los archivos o de los correos y haz que la automatización avise en lugar de fallar en silencio."}, {"titulo": "Una biblioteca de tareas", "aporta": "reúne cinco automatizaciones con instrucciones para que otra persona de la oficina las use."}], "objetivos": ["Identificar actividades que consumen tiempo de forma repetitiva.", "Diagramar el proceso actual paso a paso.", "Detectar puntos donde se producen errores o retrasos.", "Diseñar una solución de automatización adecuada.", "Evaluar cuánto tiempo podría ahorrarse con la mejora propuesta."], "habilidades": ["Análisis de procesos.", "Automatización básica.", "Diseño de flujos de trabajo.", "Organización de información.", "Resolución de problemas.", "Pensamiento sistémico."], "herramientas": ["Hojas de cálculo.", "Formularios digitales.", "Herramientas de automatización.", "Bases de datos sencillas.", "Aplicaciones web o móviles si deseas ampliar el proyecto.", "Diagramas de flujo."], "lineamientos": ["Comienza con un proceso pequeño y bien definido. Una automatización simple que funcione correctamente suele aportar más valor que una solución compleja difícil de mantener.", "Documenta cómo se realizaba el proceso antes y cómo cambia después de la mejora. Si utilizas información real, evita almacenar datos sensibles innecesarios.", "Recuerda que la meta principal es simplificar el trabajo y reducir errores, no añadir complejidad al proceso."], "otroSector": "La misma metodología puede aplicarse a clínicas, colegios, organizaciones sociales, bibliotecas, talleres, comercios, proyectos de investigación o cualquier entorno donde existan actividades repetitivas."}$f88a7d9$::jsonb,39),
('como-se-entera-un-equipo-de-que-algo-fallo-antes-que-sus-usuario','tecnologia',array['industria']::text[],'¿Cómo se entera un equipo de que algo falló antes que sus usuarios?','Diseña un sistema sencillo que vigile un servicio, detecte cuando deja de responder y avise a tiempo a quien debe actuar.','Prototipo','1 a 3 meses',52,array['Monitoreo','Alertas','Sistemas']::text[],array['crear','resolver','otro-sector']::text[],'propios','incluida','ingenieria de sistemas ingenieria de software ciberseguridad telecomunicaciones ingenieria industrial computacion e informatica redes y comunicaciones monitoreo de sistemas. programacion basica de scripts. analisis de series de tiempo. diseno de alertas utiles. visualizacion de datos. lenguaje de programacion con bibliotecas de red. hoja de calculo o base de datos sencilla. herramienta de tableros.',$f6ed842${"id": "como-se-entera-un-equipo-de-que-algo-fallo-antes-que-sus-usuario", "area": "tecnologia", "areas2": ["industria"], "titulo": "¿Cómo se entera un equipo de que algo falló antes que sus usuarios?", "resumen": "Diseña un sistema sencillo que vigile un servicio, detecte cuando deja de responder y avise a tiempo a quien debe actuar.", "tipo": "Prototipo", "tiempo": "1 a 3 meses", "horas": 52, "etiquetas": ["Monitoreo", "Alertas", "Sistemas"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "propios", "datosTexto": "propios o ficticios: puedes vigilar una página o servicio tuyo, o simular registros de un servicio con datos inventados.", "prog": "incluida", "progTexto": "Incluye programación: puedes hacerlo con apoyo de una IA o en equipo.", "abordar": "solo, con una IA como apoyo, o en equipo con alguien que aporte lo que te falta (por ejemplo, una persona de Sistemas junto con otra que conozca bien el problema). Quien presente el proyecto debe poder explicar qué hace y comprobar que funciona.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Ciberseguridad", "Telecomunicaciones", "Ingeniería Industrial", "Computación e Informática", "Redes y Comunicaciones"], "problema": ["Muchos servicios se caen y quienes los mantienen se enteran porque los usuarios reclaman. Para entonces el daño ya está hecho y no hay forma de saber cuánto duró la falla.", "Vigilar un servicio exige decidir qué medir, cada cuánto y cuándo avisar. Si se avisa por todo, las alertas se ignoran; si se avisa de menos, la falla pasa desapercibida."], "desarrollar": ["Elige una página o servicio propio, o inventa uno, y define tres indicadores: si responde, cuánto tarda y cuántos errores devuelve. Registra esas medidas a intervalos regulares y define las reglas de aviso: cuándo es una alerta y cuándo solo un dato.", "Prueba el sistema provocando una falla controlada y revisa si el aviso llegó a tiempo y con información útil. El resultado puede ser un tablero sencillo con el estado del servicio y un historial de alertas."], "ampliaciones": [{"titulo": "Varias piezas", "aporta": "vigila un conjunto de servicios y muestra cuál es la primera pieza en fallar."}, {"titulo": "Sensores y dispositivos", "aporta": "extiende el sistema a equipos conectados, como una red de sensores, y estudia qué cambia cuando los datos llegan de muy lejos."}, {"titulo": "Cansancio de alertas", "aporta": "mide cuántos avisos son útiles y ajusta las reglas para que sean pocos y valiosos."}], "objetivos": ["Definir indicadores que describan la salud de un servicio.", "Registrar medidas a intervalos regulares.", "Diseñar reglas de alerta que eviten falsas alarmas.", "Probar el sistema con una falla controlada.", "Mostrar el estado de forma clara en un tablero."], "habilidades": ["Monitoreo de sistemas.", "Programación básica de scripts.", "Análisis de series de tiempo.", "Diseño de alertas útiles.", "Visualización de datos."], "herramientas": ["Lenguaje de programación con bibliotecas de red.", "Hoja de cálculo o base de datos sencilla.", "Herramienta de tableros."], "lineamientos": ["Cuidados: vigila solo servicios tuyos o con permiso explícito de quien los administre. Enviar muchas solicitudes a un servicio ajeno puede dañarlo y está mal visto.", "Empieza con pocos indicadores y pocas alertas, y amplía solo cuando lo básico funcione."], "otroSector": "La misma lógica sirve para vigilar una línea de producción, una cadena de frío, la asistencia a un taller o cualquier proceso que deba avisar cuando se aleje de lo normal."}$f6ed842$::jsonb,40),
('clasificar-reclamos-lo-hace-mejor-una-persona-unas-reglas-o-una','tecnologia',array['negocios','derecho']::text[],'Clasificar reclamos: ¿lo hace mejor una persona, unas reglas o una IA?','Compara tres formas de clasificar reclamos o solicitudes: una persona, reglas escritas a mano y un modelo de IA, y descubre cuándo conviene cada una.','Prototipo','1 a 3 meses',52,array['Inteligencia artificial','Clasificación','Atención al cliente']::text[],array['crear','resolver','otro-sector']::text[],'ficticios','incluida','ingenieria de sistemas ingenieria de software inteligencia artificial ciencia de datos administracion derecho computacion e informatica atencion al cliente clasificacion de textos. aprendizaje automatico basico. diseno de reglas. evaluacion de resultados. comunicacion de recomendaciones. hoja de calculo. lenguaje de programacion con bibliotecas de texto, o una herramienta de ia para clasificacion. documento para el informe.',$f02ec5e${"id": "clasificar-reclamos-lo-hace-mejor-una-persona-unas-reglas-o-una", "area": "tecnologia", "areas2": ["negocios", "derecho"], "titulo": "Clasificar reclamos: ¿lo hace mejor una persona, unas reglas o una IA?", "resumen": "Compara tres formas de clasificar reclamos o solicitudes: una persona, reglas escritas a mano y un modelo de IA, y descubre cuándo conviene cada una.", "tipo": "Prototipo", "tiempo": "1 a 3 meses", "horas": 52, "etiquetas": ["Inteligencia artificial", "Clasificación", "Atención al cliente"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: crea 100 a 200 reclamos o solicitudes inventados, con la categoría correcta anotada.", "prog": "incluida", "progTexto": "Incluye programación: puedes hacerlo con apoyo de una IA o en equipo.", "abordar": "solo, con una IA como apoyo, o en equipo con alguien que aporte lo que te falta (por ejemplo, una persona de Sistemas junto con otra que conozca bien el problema). Quien presente el proyecto debe poder explicar qué hace y comprobar que funciona.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Inteligencia Artificial", "Ciencia de Datos", "Administración", "Derecho", "Computación e Informática", "Atención al Cliente"], "problema": ["Las organizaciones reciben reclamos y solicitudes de todo tipo y alguien debe decidir a qué área corresponde cada uno. Cuando llegan cientos, esa tarea es lenta, y los errores hacen que un reclamo dé vueltas días antes de llegar a quien puede resolverlo.", "Entre las soluciones está usar reglas, como «si dice factura va a Contabilidad», o un modelo de IA. Casi nadie las compara con datos."], "desarrollar": ["Redacta entre 100 y 200 reclamos ficticios de cuatro o cinco categorías, con la clasificación correcta. Pide a dos personas que los clasifiquen, escribe unas reglas basadas en palabras clave y prueba un modelo sencillo de IA.", "Mide el acierto de cada método, el tiempo que toma y qué tipo de errores comete. El resultado puede ser un informe con una recomendación sobre cuándo conviene cada enfoque."], "ampliaciones": [{"titulo": "Casos difíciles", "aporta": "agrega reclamos ambiguos y observa cuál método se equivoca más."}, {"titulo": "Una combinación", "aporta": "usa reglas para lo evidente, un modelo para lo demás y una persona para lo dudoso."}, {"titulo": "Un costo del error", "aporta": "mide cuánto cuesta equivocarse en cada categoría y ajusta el sistema."}], "objetivos": ["Preparar un conjunto de ejemplos con respuesta conocida.", "Implementar tres formas de clasificar.", "Medir acierto, tiempo y tipos de error.", "Comparar los métodos con criterios claros.", "Recomendar cuándo usar cada uno."], "habilidades": ["Clasificación de textos.", "Aprendizaje automático básico.", "Diseño de reglas.", "Evaluación de resultados.", "Comunicación de recomendaciones."], "herramientas": ["Hoja de cálculo.", "Lenguaje de programación con bibliotecas de texto, o una herramienta de IA para clasificación.", "Documento para el informe."], "lineamientos": ["Cuidados: trabaja solo con reclamos ficticios. Los reclamos reales contienen datos personales y requieren permiso de la organización.", "Una persona debe poder revisar y corregir cualquier decisión automática, sobre todo cuando afecta derechos de alguien."], "otroSector": "El mismo estudio sirve para clasificar solicitudes de soporte técnico, correos de atención al cliente, quejas ciudadanas o comentarios de un servicio."}$f02ec5e$::jsonb,41),
('dos-formas-de-construir-lo-mismo-cual-conviene-y-por-que','tecnologia',array['negocios']::text[],'Dos formas de construir lo mismo: ¿cuál conviene y por qué?','Compara dos formas de construir el mismo sistema y descubre cuándo conviene una u otra según el tamaño, el costo y el equipo.','Investigación','1 a 3 meses',52,array['Arquitectura de software','Comparación','Diseño de sistemas']::text[],array['investigar','otro-sector']::text[],'ficticios','incluida','ingenieria de sistemas ingenieria de software computacion e informatica analisis de sistemas administracion ingenieria industrial arquitectura de software. analisis de requisitos. programacion basica. evaluacion comparativa. comunicacion tecnica. lenguaje de programacion y un marco web sencillo. herramienta de diagramas. documento para el informe.',$f6e294a${"id": "dos-formas-de-construir-lo-mismo-cual-conviene-y-por-que", "area": "tecnologia", "areas2": ["negocios"], "titulo": "Dos formas de construir lo mismo: ¿cuál conviene y por qué?", "resumen": "Compara dos formas de construir el mismo sistema y descubre cuándo conviene una u otra según el tamaño, el costo y el equipo.", "tipo": "Investigación", "tiempo": "1 a 3 meses", "horas": 52, "etiquetas": ["Arquitectura de software", "Comparación", "Diseño de sistemas"], "intencion": ["investigar", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: define un problema inventado, como una tienda de comida en línea, con requisitos y números supuestos.", "prog": "incluida", "progTexto": "Incluye programación: puedes hacerlo con apoyo de una IA o en equipo.", "abordar": "solo, con una IA como apoyo, o en equipo con alguien que aporte lo que te falta (por ejemplo, una persona de Sistemas junto con otra que conozca bien el problema). Quien presente el proyecto debe poder explicar qué hace y comprobar que funciona.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Computación e Informática", "Análisis de Sistemas", "Administración", "Ingeniería Industrial"], "problema": ["Un mismo sistema se puede construir de maneras muy distintas: todo junto o dividido en piezas, con un servidor propio o con servicios ya hechos. Cada opción tiene ventajas, y la elección suele hacerse por moda.", "Pocas veces se comparan con criterios concretos como costo, complejidad, rapidez de cambio y riesgo, y por eso hay proyectos pequeños construidos con una complejidad que no necesitaban."], "desarrollar": ["Plantea un problema inventado con requisitos claros y describe dos arquitecturas posibles. Define diez criterios de comparación y puntúa cada opción con justificación.", "Construye un prototipo mínimo de cada una, o al menos el diseño detallado de sus partes clave, y compara lo que cuesta construirlas y cambiarlas. El resultado puede ser un informe con una recomendación y sus condiciones."], "ampliaciones": [{"titulo": "Cuando el sistema crece", "aporta": "estima qué pasa con cada opción si los usuarios se multiplican por diez."}, {"titulo": "El factor humano", "aporta": "incluye el tamaño y la experiencia del equipo como criterio y mira cómo cambia la decisión."}, {"titulo": "Un caso real publicado", "aporta": "compara tu análisis con la explicación que una empresa dio sobre su cambio de arquitectura."}], "objetivos": ["Describir dos arquitecturas para un mismo problema.", "Definir criterios de comparación justificados.", "Evaluar cada opción de forma sistemática.", "Construir o diseñar prototipos mínimos.", "Recomendar con condiciones claras."], "habilidades": ["Arquitectura de software.", "Análisis de requisitos.", "Programación básica.", "Evaluación comparativa.", "Comunicación técnica."], "herramientas": ["Lenguaje de programación y un marco web sencillo.", "Herramienta de diagramas.", "Documento para el informe."], "lineamientos": ["Admite que no hay una opción «mejor» en general: la conclusión depende de los supuestos que definiste.", "Si usas ejemplos de empresas, cita fuentes públicas y no atribuyas decisiones que no estén publicadas."], "otroSector": "La misma comparación sirve para decidir entre contratar o fabricar, alquilar o comprar, o un proceso manual frente a uno automatizado."}$f6e294a$::jsonb,42),
('un-sistema-de-recomendacion-como-saber-si-recomienda-bien','tecnologia',array['sociedad','arte']::text[],'Un sistema de recomendación: ¿cómo saber si recomienda bien?','Construye un recomendador sencillo y, sobre todo, aprende a evaluar si sus recomendaciones son buenas, variadas y justas.','Prototipo','1 a 3 meses',52,array['Inteligencia artificial','Recomendación','Evaluación']::text[],array['crear','resolver','otro-sector']::text[],'publicos','incluida','ingenieria de sistemas ingenieria de software inteligencia artificial ciencia de datos estadistica marketing comunicaciones computacion e informatica aprendizaje automatico basico. programacion en un lenguaje de datos. evaluacion de modelos. analisis critico de resultados. comunicacion tecnica. lenguaje de programacion para datos. cuaderno interactivo. conjuntos de datos publicos.',$fcdf4b5${"id": "un-sistema-de-recomendacion-como-saber-si-recomienda-bien", "area": "tecnologia", "areas2": ["sociedad", "arte"], "titulo": "Un sistema de recomendación: ¿cómo saber si recomienda bien?", "resumen": "Construye un recomendador sencillo y, sobre todo, aprende a evaluar si sus recomendaciones son buenas, variadas y justas.", "tipo": "Prototipo", "tiempo": "1 a 3 meses", "horas": 52, "etiquetas": ["Inteligencia artificial", "Recomendación", "Evaluación"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "publicos", "datosTexto": "públicos o ficticios: usa un conjunto abierto de valoraciones de películas, libros o música, o inventa uno pequeño.", "prog": "incluida", "progTexto": "Incluye programación: puedes hacerlo con apoyo de una IA o en equipo.", "abordar": "solo, con una IA como apoyo, o en equipo con alguien que aporte lo que te falta (por ejemplo, una persona de Sistemas junto con otra que conozca bien el problema). Quien presente el proyecto debe poder explicar qué hace y comprobar que funciona.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Inteligencia Artificial", "Ciencia de Datos", "Estadística", "Marketing", "Comunicaciones", "Computación e Informática"], "problema": ["Casi todas las plataformas recomiendan algo: películas, productos, canciones, cursos. Pero pocas personas se preguntan si la recomendación es buena para ellas o solo les muestra más de lo mismo.", "Construir un recomendador es relativamente fácil. Lo difícil es medir si funciona, si cae en repetir siempre lo popular y si trata bien a los gustos poco comunes."], "desarrollar": ["Elige un conjunto abierto de valoraciones y construye un recomendador simple, por ejemplo uno que sugiera lo que les gustó a personas parecidas. Separa una parte de los datos para comprobar si acierta en lo que no vio.", "Evalúa tres cosas: cuánto acierta, qué tan variadas son las sugerencias y qué pasa con los gustos poco comunes. El resultado puede ser un informe con los números y algunos ejemplos concretos."], "ampliaciones": [{"titulo": "Siempre lo mismo", "aporta": "mide cuánto se repiten las mismas obras populares en las recomendaciones."}, {"titulo": "Un arranque difícil", "aporta": "estudia qué recomendar a un usuario nuevo sin historial."}, {"titulo": "Explicar la sugerencia", "aporta": "agrega una frase que diga por qué se recomienda cada obra y pregunta a otras personas si les resulta útil."}], "objetivos": ["Construir un recomendador sencillo.", "Separar datos de entrenamiento y de prueba.", "Medir acierto y variedad.", "Analizar el trato a gustos poco comunes.", "Reportar las limitaciones con claridad."], "habilidades": ["Aprendizaje automático básico.", "Programación en un lenguaje de datos.", "Evaluación de modelos.", "Análisis crítico de resultados.", "Comunicación técnica."], "herramientas": ["Lenguaje de programación para datos.", "Cuaderno interactivo.", "Conjuntos de datos públicos."], "lineamientos": ["Usa datos públicos o inventados y no mezcles información de personas reales identificables.", "No presentes el recomendador como una verdad: explica a qué personas y gustos sirve y a cuáles no."], "otroSector": "La misma estructura se usa para recomendar cursos, libros de una biblioteca, productos de una tienda, rutas de transporte o actividades de un club."}$fcdf4b5$::jsonb,43),
('un-asistente-que-responde-preguntas-sobre-tus-propios-documentos','tecnologia',array['educacion']::text[],'Un asistente que responde preguntas sobre tus propios documentos','Construye un asistente que responda preguntas usando solo un conjunto de documentos que tú le des, y compruébalo con preguntas que sabes responder.','Prototipo','1 a 3 meses',52,array['Inteligencia artificial','Documentos','Búsqueda de información']::text[],array['crear','resolver','otro-sector']::text[],'propios','incluida','ingenieria de sistemas ingenieria de software inteligencia artificial ciencia de datos educacion derecho bibliotecologia computacion e informatica busqueda de informacion. modelos de lenguaje. programacion en un lenguaje de datos. evaluacion de sistemas de ia. comunicacion honesta de resultados. lenguaje de programacion y bibliotecas de procesamiento de texto. servicios de modelos de lenguaje o modelos abiertos. hoja de calculo para evaluar las respuestas.',$f4c1c0f${"id": "un-asistente-que-responde-preguntas-sobre-tus-propios-documentos", "area": "tecnologia", "areas2": ["educacion"], "titulo": "Un asistente que responde preguntas sobre tus propios documentos", "resumen": "Construye un asistente que responda preguntas usando solo un conjunto de documentos que tú le des, y compruébalo con preguntas que sabes responder.", "tipo": "Prototipo", "tiempo": "1 a 3 meses", "horas": 52, "etiquetas": ["Inteligencia artificial", "Documentos", "Búsqueda de información"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "propios", "datosTexto": "propios o públicos: usa un conjunto pequeño de documentos tuyos o de acceso libre, como manuales, reglamentos o apuntes.", "prog": "incluida", "progTexto": "Incluye programación: puedes hacerlo con apoyo de una IA o en equipo.", "abordar": "solo, con una IA como apoyo, o en equipo con alguien que aporte lo que te falta (por ejemplo, una persona de Sistemas junto con otra que conozca bien el problema). Quien presente el proyecto debe poder explicar qué hace y comprobar que funciona.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Inteligencia Artificial", "Ciencia de Datos", "Educación", "Derecho", "Bibliotecología", "Computación e Informática"], "problema": ["Las organizaciones y los estudiantes acumulan reglamentos, manuales y apuntes que casi nadie lee completos. Cuando alguien tiene una duda, busca a mano o pregunta a otra persona, y las respuestas varían.", "Un asistente basado en esos documentos promete ahorrar tiempo, pero puede inventar respuestas que suenan convincentes y no están en ninguna parte."], "desarrollar": ["Reúne 10 a 20 documentos y prepara 30 preguntas cuyas respuestas conozcas, algunas fáciles, otras difíciles y algunas que no están en los documentos. Construye un asistente que busque los fragmentos relevantes y redacte la respuesta indicando de dónde la sacó.", "Evalúa cuántas veces acierta, cuántas veces inventa algo y qué hace cuando la respuesta no existe. El resultado puede ser un prototipo funcional y un informe honesto con sus límites."], "ampliaciones": [{"titulo": "Siempre con fuente", "aporta": "haz que cada respuesta indique el documento y la página de donde sale."}, {"titulo": "Admitir que no sabe", "aporta": "entrena al asistente para decir «no lo encuentro» cuando no hay una respuesta."}, {"titulo": "Probarlo con otras personas", "aporta": "pide a cinco personas que lo usen y comprueba si les resulta útil."}], "objetivos": ["Preparar una colección de documentos y preguntas de prueba.", "Construir un asistente que cite sus fuentes.", "Medir aciertos y respuestas inventadas.", "Manejar los casos sin respuesta.", "Documentar los límites del sistema."], "habilidades": ["Búsqueda de información.", "Modelos de lenguaje.", "Programación en un lenguaje de datos.", "Evaluación de sistemas de IA.", "Comunicación honesta de resultados."], "herramientas": ["Lenguaje de programación y bibliotecas de procesamiento de texto.", "Servicios de modelos de lenguaje o modelos abiertos.", "Hoja de cálculo para evaluar las respuestas."], "lineamientos": ["Cuidados: usa solo documentos que puedas compartir o que sean tuyos. No subas reglamentos confidenciales ni datos personales a un servicio externo.", "Advierte a quien lo use que el asistente puede equivocarse y que las respuestas importantes deben verificarse en el documento original."], "otroSector": "Un asistente como este sirve para reglamentos de un colegio, manuales de un negocio, historias clínicas anónimas de práctica, leyes y normas o material de estudio de un curso."}$f4c1c0f$::jsonb,44),
('que-le-pasa-a-una-ia-cuando-los-datos-no-son-perfectos','tecnologia',array['ciencias']::text[],'¿Qué le pasa a una IA cuando los datos no son perfectos?','Explora cómo la calidad de los datos influye en el comportamiento de un modelo de inteligencia artificial. Descubre qué ocurre cuando la información contiene errores, valores faltantes o categorías insuficientemente representadas, y analiza cómo estas situaciones pueden afectar la capacidad de un sistema para aprender y tomar decisiones.','Investigación','2 a 5 meses',91,array['Inteligencia artificial','Calidad de datos','Ciencia de datos']::text[],array['investigar','otro-sector']::text[],'publicos','incluida','ingenieria de sistemas ciencia de datos estadistica matematica economia ingenieria industrial inteligencia artificial fisica estadistica. ciencia de datos. aprendizaje automatico. diseno experimental. limpieza de datos. interpretacion de metricas. visualizacion de informacion. python. pandas. scikit-learn. jupyter notebook. bibliotecas de visualizacion de datos. conjuntos de datos publicos.',$f4d7ca8${"id": "que-le-pasa-a-una-ia-cuando-los-datos-no-son-perfectos", "area": "tecnologia", "areas2": ["ciencias"], "titulo": "¿Qué le pasa a una IA cuando los datos no son perfectos?", "resumen": "Explora cómo la calidad de los datos influye en el comportamiento de un modelo de inteligencia artificial. Descubre qué ocurre cuando la información contiene errores, valores faltantes o categorías insuficientemente representadas, y analiza cómo estas situaciones pueden afectar la capacidad de un sistema para aprender y tomar decisiones.", "tipo": "Investigación", "tiempo": "2 a 5 meses", "horas": 91, "etiquetas": ["Inteligencia artificial", "Calidad de datos", "Ciencia de datos"], "intencion": ["investigar", "otro-sector"], "datos": "publicos", "datosTexto": "conjuntos de datos públicos y simulados: puedes utilizar bases de datos abiertas y generar versiones modificadas para estudiar distintos escenarios.", "prog": "incluida", "progTexto": "Incluye programación: puedes hacerlo con apoyo de una IA o en equipo.", "abordar": "solo, con una IA como apoyo, o en equipo con alguien que aporte lo que te falta (por ejemplo, una persona de Sistemas junto con otra que conozca bien el problema). Quien presente el proyecto debe poder explicar qué hace y comprobar que funciona.", "carreras": ["Ingeniería de Sistemas", "Ciencia de Datos", "Estadística", "Matemática", "Economía", "Ingeniería Industrial", "Inteligencia Artificial", "Física"], "problema": ["Cuando se habla de inteligencia artificial, suele prestarse mucha atención a los algoritmos y modelos utilizados. Sin embargo, una gran parte del desempeño de cualquier sistema depende de la calidad de los datos con los que fue entrenado.", "En situaciones reales es habitual trabajar con información incompleta, registros con errores, datos duplicados, categorías poco frecuentes o muestras que no representan adecuadamente la realidad que se desea estudiar. Estos problemas pueden introducir sesgos, reducir la precisión de los modelos o provocar decisiones incorrectas.", "Muchas veces un modelo aparentemente inteligente deja de funcionar correctamente no por limitaciones del algoritmo, sino porque los datos utilizados para entrenarlo presentan deficiencias difíciles de detectar a simple vista.", "Comprender esta relación permite desarrollar una visión más crítica sobre los resultados obtenidos por los sistemas de inteligencia artificial y ayuda a valorar la importancia de construir conjuntos de datos confiables."], "desarrollar": ["Selecciona un conjunto de datos adecuado para un problema de clasificación y entrena un modelo base que sirva como referencia.", "Posteriormente, genera distintas versiones modificadas del mismo conjunto de datos incorporando problemas controlados como:", {"lista": ["Valores faltantes.", "Etiquetas incorrectas.", "Datos duplicados.", "Categorías desequilibradas.", "Registros incompletos.", "Ruido aleatorio."]}, "Compara cómo cambian las métricas del modelo en cada escenario y documenta las diferencias observadas."], "ampliaciones": [{"titulo": "Comparar algoritmos", "aporta": "analiza si algunos modelos toleran mejor ciertos problemas de calidad de datos que otros."}, {"titulo": "Evaluar estrategias de limpieza", "aporta": "estudia cómo cambian los resultados después de corregir errores o completar valores faltantes."}, {"titulo": "Diseñar indicadores de calidad", "aporta": "desarrolla métricas que permitan evaluar la calidad de un conjunto de datos antes del entrenamiento."}], "objetivos": ["Seleccionar un conjunto de datos adecuado para experimentación.", "Establecer una línea base de desempeño utilizando datos sin modificaciones.", "Introducir problemas controlados de calidad.", "Evaluar cómo afectan estos problemas al modelo.", "Comparar resultados entre distintos escenarios.", "Comunicar conclusiones fundamentadas en evidencia experimental."], "habilidades": ["Estadística.", "Ciencia de datos.", "Aprendizaje automático.", "Diseño experimental.", "Limpieza de datos.", "Interpretación de métricas.", "Visualización de información."], "herramientas": ["Python.", "Pandas.", "Scikit-learn.", "Jupyter Notebook.", "Bibliotecas de visualización de datos.", "Conjuntos de datos públicos."], "lineamientos": ["Documenta cuidadosamente todas las modificaciones realizadas sobre los datos para que los experimentos puedan reproducirse posteriormente.", "Mantén condiciones comparables entre pruebas y cambia únicamente los factores que deseas estudiar. Evita generalizar resultados obtenidos a partir de un único conjunto de datos o un único algoritmo.", "Recuerda que el objetivo del proyecto no es encontrar el modelo con mejor rendimiento, sino comprender cómo la calidad de los datos influye en los resultados obtenidos y qué consecuencias puede tener en aplicaciones reales."], "otroSector": "La misma metodología puede aplicarse a predicciones económicas, investigaciones médicas con datos anonimizados, estudios ambientales, sistemas de mantenimiento predictivo, análisis de comportamiento de usuarios o procesos industriales basados en datos."}$f4d7ca8$::jsonb,45),
('y-si-tu-recibo-de-luz-te-avisara-cuando-algo-consume-de-mas','tecnologia',array['ambiente']::text[],'¿Y si tu recibo de luz te avisara cuando algo consume de más?','Investiga cómo analizar patrones de consumo eléctrico para identificar comportamientos inusuales que podrían indicar fallas, desperdicios de energía, configuraciones ineficientes o situaciones que requieren una revisión más detallada. Descubre cómo los sistemas de análisis de datos y aprendizaje automático pueden ayudar a detectar cambios que serían difíciles de observar manualmente.','Prototipo','2 a 6 meses',104,array['Inteligencia artificial','Energía','Análisis predictivo']::text[],array['crear','resolver','otro-sector']::text[],'publicos','incluida','ingenieria electrica ingenieria electronica ingenieria de sistemas ciencia de datos ingenieria ambiental estadistica fisica ingenieria industrial inteligencia artificial estadistica. series temporales. ciencia de datos. aprendizaje automatico. limpieza y preparacion de datos. visualizacion de informacion. interpretacion de modelos analiticos. python. pandas. scikit-learn. jupyter notebook. bibliotecas de visualizacion. conjuntos de datos abiertos o simulados.',$f89cbac${"id": "y-si-tu-recibo-de-luz-te-avisara-cuando-algo-consume-de-mas", "area": "tecnologia", "areas2": ["ambiente"], "titulo": "¿Y si tu recibo de luz te avisara cuando algo consume de más?", "resumen": "Investiga cómo analizar patrones de consumo eléctrico para identificar comportamientos inusuales que podrían indicar fallas, desperdicios de energía, configuraciones ineficientes o situaciones que requieren una revisión más detallada. Descubre cómo los sistemas de análisis de datos y aprendizaje automático pueden ayudar a detectar cambios que serían difíciles de observar manualmente.", "tipo": "Prototipo", "tiempo": "2 a 6 meses", "horas": 104, "etiquetas": ["Inteligencia artificial", "Energía", "Análisis predictivo"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "publicos", "datosTexto": "públicos o simulados: puedes utilizar conjuntos de datos abiertos, registros históricos simulados o series temporales generadas para experimentar con distintos escenarios.", "prog": "incluida", "progTexto": "Incluye programación: puedes hacerlo con apoyo de una IA o en equipo.", "abordar": "solo, con una IA como apoyo, o en equipo con alguien que aporte lo que te falta (por ejemplo, una persona de Sistemas junto con otra que conozca bien el problema). Quien presente el proyecto debe poder explicar qué hace y comprobar que funciona.", "carreras": ["Ingeniería Eléctrica", "Ingeniería Electrónica", "Ingeniería de Sistemas", "Ciencia de Datos", "Ingeniería Ambiental", "Estadística", "Física", "Ingeniería Industrial", "Inteligencia Artificial"], "problema": ["En viviendas, oficinas, industrias y edificios públicos, el consumo eléctrico varía constantemente en función de horarios, actividades, estaciones del año y características de los equipos utilizados. Estas variaciones suelen formar parte del funcionamiento normal de una instalación.", "Sin embargo, también pueden aparecer cambios inesperados: un equipo que empieza a consumir más energía de lo habitual, un sistema que permanece encendido cuando no debería o un comportamiento anómalo que pasa desapercibido durante días o semanas.", "Cuando únicamente se observan los consumos totales, resulta difícil distinguir entre una variación normal y una situación que merece atención. Como consecuencia, pueden producirse pérdidas económicas, desperdicio de energía o retrasos en la detección de problemas.", "El desafío consiste en desarrollar métodos capaces de aprender cómo suele comportarse un sistema y señalar situaciones que se alejan significativamente de ese patrón habitual."], "desarrollar": ["Construye una herramienta capaz de procesar registros históricos de consumo eléctrico e identificar comportamientos inusuales mediante reglas estadísticas o modelos de aprendizaje automático.", "El sistema puede incluir:", {"lista": ["Visualización temporal de consumos.", "Identificación automática de anomalías.", "Comparación con patrones históricos.", "Alertas basadas en umbrales o modelos predictivos.", "Explicaciones simples sobre los criterios utilizados."]}, "El resultado puede presentarse como un informe analítico, un panel interactivo o una aplicación experimental."], "ampliaciones": [{"titulo": "Comparar métodos", "aporta": "analiza las diferencias entre enfoques estadísticos tradicionales y modelos de aprendizaje automático."}, {"titulo": "Detección en tiempo real", "aporta": "diseña una solución capaz de evaluar nuevos registros a medida que llegan."}, {"titulo": "Predicción de consumos", "aporta": "explora cómo estimar el comportamiento esperado y detectar desviaciones futuras antes de que ocurran."}], "objetivos": ["Conseguir o generar un conjunto de datos adecuado.", "Analizar patrones habituales de consumo.", "Diseñar criterios para detectar anomalías.", "Implementar y comparar distintos métodos de detección.", "Evaluar la calidad de los resultados obtenidos.", "Comunicar claramente las limitaciones del sistema desarrollado."], "habilidades": ["Estadística.", "Series temporales.", "Ciencia de datos.", "Aprendizaje automático.", "Limpieza y preparación de datos.", "Visualización de información.", "Interpretación de modelos analíticos."], "herramientas": ["Python.", "Pandas.", "Scikit-learn.", "Jupyter Notebook.", "Bibliotecas de visualización.", "Conjuntos de datos abiertos o simulados."], "lineamientos": ["No confundas una anomalía estadística con una falla eléctrica confirmada. Una desviación detectada por el sistema únicamente indica que el comportamiento observado difiere de los patrones habituales y requiere una revisión más detallada.", "Documenta claramente las decisiones tomadas durante el análisis, los supuestos utilizados y las limitaciones de cada modelo. Utiliza únicamente datos que respeten la privacidad de las personas y evita trabajar con información sensible innecesaria.", "Recuerda que el objetivo del proyecto no es construir un sistema perfecto, sino comprender cómo pueden utilizarse los datos para identificar situaciones que merecen atención."], "otroSector": "El mismo enfoque puede utilizarse para detectar consumos anómalos de agua, pérdidas de combustible, variaciones inusuales en procesos industriales, cambios sospechosos en redes informáticas, patrones financieros atípicos o comportamientos anómalos en sistemas de monitoreo ambiental."}$f89cbac$::jsonb,46),
('una-red-de-sensores-para-vigilar-el-ambiente','tecnologia',array['ambiente']::text[],'Una red de sensores para vigilar el ambiente','Explora cómo recopilar información del entorno de forma automática para comprender cómo cambian las condiciones de un espacio a lo largo del tiempo. Diseña un sistema capaz de medir variables ambientales, almacenar registros históricos y visualizar tendencias que normalmente pasan desapercibidas cuando solo se realizan observaciones ocasionales.','Prototipo','2 a 6 meses',104,array['Internet de las cosas','Electrónica','Monitoreo']::text[],array['crear','resolver','otro-sector']::text[],'propios','incluida','ingenieria electronica ingenieria mecatronica ingenieria de sistemas ingenieria ambiental fisica ingenieria industrial ciencia de datos internet de las cosas (iot) electronica basica. programacion de microcontroladores. internet de las cosas (iot). comunicacion entre dispositivos. bases de datos. visualizacion de informacion. analisis de datos ambientales. esp32, arduino u otro microcontrolador similar. sensores ambientales. python o javascript. base de datos. panel web o herramienta de visualizacion. protoboard y componentes electronicos basicos.',$f8ff589${"id": "una-red-de-sensores-para-vigilar-el-ambiente", "area": "tecnologia", "areas2": ["ambiente"], "titulo": "Una red de sensores para vigilar el ambiente", "resumen": "Explora cómo recopilar información del entorno de forma automática para comprender cómo cambian las condiciones de un espacio a lo largo del tiempo. Diseña un sistema capaz de medir variables ambientales, almacenar registros históricos y visualizar tendencias que normalmente pasan desapercibidas cuando solo se realizan observaciones ocasionales.", "tipo": "Prototipo", "tiempo": "2 a 6 meses", "horas": 104, "etiquetas": ["Internet de las cosas", "Electrónica", "Monitoreo"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes mediante sensores y dispositivos instalados por ti.", "prog": "incluida", "progTexto": "Incluye programación y electrónica básica: puedes hacerlo con apoyo de una IA o en equipo.", "abordar": "solo, con una IA como apoyo, o en equipo con alguien que aporte lo que te falta (por ejemplo, una persona de Sistemas junto con otra que conozca bien el problema). Quien presente el proyecto debe poder explicar qué hace y comprobar que funciona.", "carreras": ["Ingeniería Electrónica", "Ingeniería Mecatrónica", "Ingeniería de Sistemas", "Ingeniería Ambiental", "Física", "Ingeniería Industrial", "Ciencia de Datos", "Internet de las Cosas (IoT)"], "problema": ["La temperatura, la humedad y otras condiciones ambientales cambian constantemente durante el día. Un aula puede calentarse progresivamente conforme aumenta la ocupación. Un almacén puede presentar niveles de humedad que afecten los materiales guardados. Un huerto puede experimentar variaciones que influyan en el desarrollo de las plantas.", "A pesar de que estos cambios ocurren continuamente, muchas veces no existen registros que permitan observarlos de forma sistemática. Sin datos históricos resulta difícil identificar patrones, detectar problemas o tomar decisiones informadas sobre ventilación, almacenamiento, eficiencia energética o condiciones de trabajo.", "Los sistemas de monitoreo permiten transformar observaciones aisladas en información continua que puede analizarse y utilizarse para comprender mejor un entorno."], "desarrollar": ["Construye una estación de monitoreo capaz de recopilar información ambiental utilizando sensores conectados a un microcontrolador.", "El sistema puede incluir:", {"lista": ["Medición de temperatura.", "Medición de humedad.", "Registro de fecha y hora.", "Almacenamiento de datos.", "Visualización básica de resultados."]}, "Posteriormente, diseña un panel donde los registros puedan consultarse mediante gráficos, indicadores o series temporales que faciliten su interpretación."], "ampliaciones": [{"titulo": "Un lugar con historia", "aporta": "mide un espacio donde el ambiente importe de verdad, como un huerto, un aula que se calienta o un depósito de materiales, y compara los datos con lo que sienten quienes lo usan."}, {"titulo": "Ciencia ciudadana", "aporta": "diseña una guía sencilla para que un grupo de vecinos o estudiantes arme su propia estación y comparta sus lecturas."}, {"titulo": "Datos que se ven", "aporta": "presenta las lecturas como un panel en vivo o una pequeña muestra para que la comunidad vea cómo respira un espacio."}], "objetivos": ["Seleccionar sensores adecuados para las variables que se desean medir.", "Diseñar y construir el circuito de monitoreo.", "Programar la recopilación automática de datos.", "Implementar mecanismos de almacenamiento.", "Desarrollar visualizaciones que faciliten el análisis de la información.", "Evaluar la estabilidad y calidad de las mediciones obtenidas."], "habilidades": ["Electrónica básica.", "Programación de microcontroladores.", "Internet de las cosas (IoT).", "Comunicación entre dispositivos.", "Bases de datos.", "Visualización de información.", "Análisis de datos ambientales."], "herramientas": ["ESP32, Arduino u otro microcontrolador similar.", "Sensores ambientales.", "Python o JavaScript.", "Base de datos.", "Panel web o herramienta de visualización.", "Protoboard y componentes electrónicos básicos."], "lineamientos": ["Trabaja siempre con voltajes seguros y evita realizar conexiones improvisadas o instalaciones eléctricas que puedan representar riesgos.", "Documenta el modelo de los sensores utilizados, su precisión y las limitaciones conocidas. No presentes las mediciones obtenidas como si provinieran de instrumentos certificados para uso profesional o industrial.", "Registra las condiciones en las que se realizaron las pruebas para facilitar la interpretación de los resultados y la comparación entre distintos periodos de observación."], "otroSector": "La misma metodología puede adaptarse al monitoreo de huertos, invernaderos, almacenes de alimentos, laboratorios, aulas, oficinas, espacios de trabajo, estaciones meteorológicas o proyectos de investigación ambiental."}$f8ff589$::jsonb,47),
('mismos-datos-distintos-algoritmos-cual-decide-mejor','tecnologia',array['ciencias']::text[],'Mismos datos, distintos algoritmos: ¿cuál decide mejor?','Imagina cómo distintos algoritmos de inteligencia artificial responden al mismo problema cuando trabajan bajo las mismas condiciones. Diseña un entorno experimental que permita comparar resultados de manera justa, comprender las fortalezas y limitaciones de cada modelo y analizar cómo influyen los datos en el desempeño obtenido.','Prototipo','2 a 6 meses',104,array['Inteligencia artificial','Experimentación','Ciencia de datos']::text[],array['crear','resolver','otro-sector']::text[],'publicos','incluida','ingenieria de sistemas ciencia de datos matematica estadistica fisica economia ingenieria industrial inteligencia artificial estadistica. aprendizaje automatico. programacion. ciencia de datos. diseno experimental. visualizacion de informacion. evaluacion de modelos predictivos. python. scikit-learn. pandas. jupyter notebook. streamlit o tecnologias web similares. bibliotecas de visualizacion de datos.',$ffda224${"id": "mismos-datos-distintos-algoritmos-cual-decide-mejor", "area": "tecnologia", "areas2": ["ciencias"], "titulo": "Mismos datos, distintos algoritmos: ¿cuál decide mejor?", "resumen": "Imagina cómo distintos algoritmos de inteligencia artificial responden al mismo problema cuando trabajan bajo las mismas condiciones. Diseña un entorno experimental que permita comparar resultados de manera justa, comprender las fortalezas y limitaciones de cada modelo y analizar cómo influyen los datos en el desempeño obtenido.", "tipo": "Prototipo", "tiempo": "2 a 6 meses", "horas": 104, "etiquetas": ["Inteligencia artificial", "Experimentación", "Ciencia de datos"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "publicos", "datosTexto": "conjuntos de datos públicos: puedes utilizar bases de datos abiertas disponibles para investigación o aprendizaje.", "prog": "incluida", "progTexto": "Incluye programación: puedes hacerlo con apoyo de una IA o en equipo.", "abordar": "solo, con una IA como apoyo, o en equipo con alguien que aporte lo que te falta (por ejemplo, una persona de Sistemas junto con otra que conozca bien el problema). Quien presente el proyecto debe poder explicar qué hace y comprobar que funciona.", "carreras": ["Ingeniería de Sistemas", "Ciencia de Datos", "Matemática", "Estadística", "Física", "Economía", "Ingeniería Industrial", "Inteligencia Artificial"], "problema": ["Cuando se estudia inteligencia artificial es común encontrar afirmaciones sobre modelos que parecen superiores a otros. Sin embargo, un algoritmo que funciona muy bien en un conjunto de datos puede ofrecer resultados mucho más modestos en otro contexto.", "Muchas comparaciones se realizan utilizando configuraciones diferentes, conjuntos de datos distintos o criterios de evaluación poco consistentes. Esto dificulta comprender qué ventajas ofrece realmente cada enfoque y puede llevar a conclusiones engañosas.", "Además, las métricas utilizadas en inteligencia artificial no siempre son fáciles de interpretar. Un modelo puede presentar una alta precisión general y aun así cometer errores importantes en determinadas situaciones.", "Por ello, resulta fundamental disponer de entornos donde los experimentos sean reproducibles, comparables y transparentes."], "desarrollar": ["Desarrolla una plataforma que permita cargar conjuntos de datos y ejecutar distintos algoritmos de clasificación bajo condiciones equivalentes.", "El sistema puede incluir:", {"lista": ["Selección de conjuntos de datos.", "Ejecución de múltiples algoritmos.", "Comparación de resultados.", "Visualización de métricas.", "Registro de experimentos realizados.", "Panel de análisis de desempeño."]}, "El objetivo no es únicamente obtener el mejor resultado, sino comprender por qué distintos modelos se comportan de formas diferentes."], "ampliaciones": [{"titulo": "Comparar familias de modelos", "aporta": "analiza diferencias entre algoritmos tradicionales, ensambles y técnicas más avanzadas."}, {"titulo": "Visualizar decisiones", "aporta": "explora formas de representar cómo llegan los modelos a determinadas predicciones."}, {"titulo": "Automatizar experimentos", "aporta": "diseña un sistema que ejecute múltiples configuraciones y genere comparaciones automáticas."}], "objetivos": ["Seleccionar uno o más problemas de clasificación adecuados.", "Preparar conjuntos de datos para los experimentos.", "Implementar distintos algoritmos bajo condiciones comparables.", "Comparar métricas de desempeño.", "Interpretar fortalezas y limitaciones de cada modelo.", "Presentar resultados mediante herramientas visuales y comprensibles."], "habilidades": ["Estadística.", "Aprendizaje automático.", "Programación.", "Ciencia de datos.", "Diseño experimental.", "Visualización de información.", "Evaluación de modelos predictivos."], "herramientas": ["Python.", "Scikit-learn.", "Pandas.", "Jupyter Notebook.", "Streamlit o tecnologías web similares.", "Bibliotecas de visualización de datos."], "lineamientos": ["Separa claramente los datos utilizados para entrenamiento y evaluación. Utiliza procedimientos consistentes para garantizar comparaciones justas entre algoritmos.", "Evita interpretar una única métrica como evidencia suficiente de superioridad. Diferentes problemas pueden requerir distintos criterios de evaluación.", "Documenta todas las decisiones experimentales realizadas, incluyendo parámetros, conjuntos de datos utilizados y métodos de validación aplicados.", "Recuerda que el objetivo principal es comprender el comportamiento de los modelos y no simplemente encontrar el algoritmo con el valor numérico más alto."], "otroSector": "La misma plataforma puede utilizarse para estudiar predicciones económicas, clasificación de imágenes, análisis ambiental, detección de enfermedades en datos médicos, mantenimiento predictivo, análisis de textos o investigaciones científicas basadas en datos."}$ffda224$::jsonb,48),
('un-pequeno-robot-que-se-mueve-solo','tecnologia',array['industria']::text[],'Un pequeño robot que se mueve solo','Imagina cómo combinar electrónica, programación y mecánica para construir un robot capaz de percibir su entorno y tomar decisiones sencillas de manera autónoma. Descubre cómo distintos componentes trabajan juntos para que una máquina interprete información del mundo físico y actúe sin recibir instrucciones constantes.','Prototipo','2 a 8 meses',130,array['Robótica','Electrónica','Automatización']::text[],array['crear','resolver','otro-sector']::text[],'propios','incluida','ingenieria mecatronica ingenieria electronica ingenieria mecanica ingenieria de sistemas fisica ingenieria industrial automatizacion internet de las cosas electronica basica. mecanica aplicada. programacion de microcontroladores. sensores y actuadores. robotica movil. resolucion de problemas. integracion de sistemas. arduino, esp32 o plataformas similares. motores y controladores de motores. sensores ultrasonicos, infrarrojos u otros equivalentes. baterias adecuadas para alimentacion segura. materiales para la estructura fisica del robot. herramientas de programacion y depuracion.',$f16fdb5${"id": "un-pequeno-robot-que-se-mueve-solo", "area": "tecnologia", "areas2": ["industria"], "titulo": "Un pequeño robot que se mueve solo", "resumen": "Imagina cómo combinar electrónica, programación y mecánica para construir un robot capaz de percibir su entorno y tomar decisiones sencillas de manera autónoma. Descubre cómo distintos componentes trabajan juntos para que una máquina interprete información del mundo físico y actúe sin recibir instrucciones constantes.", "tipo": "Prototipo", "tiempo": "2 a 8 meses", "horas": 130, "etiquetas": ["Robótica", "Electrónica", "Automatización"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "propios", "datosTexto": "mediciones propias y escenarios controlados: puedes realizar pruebas en entornos diseñados por ti mismo y registrar el comportamiento del robot durante cada experimento.", "prog": "incluida", "progTexto": "Incluye programación y electrónica básica: puedes hacerlo con apoyo de una IA o en equipo.", "abordar": "solo, con una IA como apoyo, o en equipo con alguien que aporte lo que te falta (por ejemplo, una persona de Sistemas junto con otra que conozca bien el problema). Quien presente el proyecto debe poder explicar qué hace y comprobar que funciona.", "carreras": ["Ingeniería Mecatrónica", "Ingeniería Electrónica", "Ingeniería Mecánica", "Ingeniería de Sistemas", "Física", "Ingeniería Industrial", "Automatización", "Internet de las Cosas"], "problema": ["En industrias, almacenes, centros logísticos, laboratorios e incluso hogares, existen tareas que requieren desplazarse, detectar obstáculos, reconocer condiciones del entorno y reaccionar frente a ellas. Muchas de estas actividades son repetitivas, demandan supervisión constante o deben realizarse en lugares donde la presencia humana no siempre es práctica.", "La robótica surge como una forma de abordar estos desafíos integrando sensores, actuadores y software capaces de interactuar con el entorno. Sin embargo, lograr que un robot tome decisiones aparentemente simples puede resultar mucho más complejo de lo que parece.", "Detectar un obstáculo es solo una parte del problema. El robot también debe decidir cómo reaccionar, cuándo cambiar de dirección, qué ruta seguir y cómo adaptarse cuando las condiciones del entorno cambian."], "desarrollar": ["Diseña y construye un robot móvil capaz de desplazarse dentro de un espacio delimitado.", "El sistema debe ser capaz de:", {"lista": ["Avanzar de forma autónoma.", "Detectar obstáculos.", "Cambiar de dirección cuando sea necesario.", "Continuar desplazándose después de evitar un obstáculo.", "Registrar observaciones sobre su comportamiento durante las pruebas."]}, "El proyecto puede comenzar con reglas simples de navegación y evolucionar hacia comportamientos más complejos conforme se obtengan resultados."], "ampliaciones": [{"titulo": "Una misión concreta", "aporta": "dale al robot un trabajo real y acotado, como recorrer un pasillo o llevar un objeto de un punto a otro, y mide qué tan bien lo cumple."}, {"titulo": "Un robot para enseñar", "aporta": "adapta el diseño y escribe una guía de armado para que escolares aprendan robótica con él."}, {"titulo": "Un explorador que cuenta lo que vio", "aporta": "haz que registre su recorrido y muestre un mapa de lo que encontró."}], "objetivos": ["Diseñar la estructura física del robot.", "Seleccionar sensores y actuadores adecuados.", "Construir el circuito electrónico.", "Programar el sistema de control.", "Implementar mecanismos de detección de obstáculos.", "Evaluar el comportamiento del robot en distintos escenarios.", "Documentar problemas encontrados y soluciones aplicadas."], "habilidades": ["Electrónica básica.", "Mecánica aplicada.", "Programación de microcontroladores.", "Sensores y actuadores.", "Robótica móvil.", "Resolución de problemas.", "Integración de sistemas."], "herramientas": ["Arduino, ESP32 o plataformas similares.", "Motores y controladores de motores.", "Sensores ultrasónicos, infrarrojos u otros equivalentes.", "Baterías adecuadas para alimentación segura.", "Materiales para la estructura física del robot.", "Herramientas de programación y depuración."], "lineamientos": ["Utiliza componentes de baja tensión y verifica todas las conexiones antes de realizar pruebas. Trabaja siempre en espacios controlados donde un fallo del robot no represente riesgos para personas, animales o equipos.", "Documenta los errores observados durante las pruebas y registra las condiciones en las que ocurrieron. En robótica, los fallos también forman parte importante del proceso de aprendizaje y mejora.", "Evita presentar el sistema como completamente autónomo o apto para entornos reales sin realizar pruebas adicionales y validar adecuadamente su desempeño."], "otroSector": "Los principios desarrollados en este proyecto pueden aplicarse a robots agrícolas, sistemas de inspección industrial, logística automatizada, monitoreo ambiental, educación tecnológica, asistencia doméstica o exploración de espacios de difícil acceso."}$f16fdb5$::jsonb,49)
